module nfkbDynamicsDetection
module atacSeqDetection
module rnaSeqDetection

manifest BoneMarrowCells
manifest PBS
manifest CompleteMCM
manifest MCSF
manifest Fibronectin
manifest HoechstStain
manifest LPS
manifest TNFa
manifest PolyIC
manifest CpG
manifest PAM2CSK4
manifest IL1b
manifest Accutase
manifest TransposaseReactionMix
manifest ATACLibraryPrimers
manifest NexteraXTKit
manifest RLT_Buffer

instructions:

// ============================================================
// Macrophage memory emerges from coordinated transcription
// factor and chromatin dynamics
// Wang, Son, Gorin et al., Cell Systems 16, 101171 (2025)
// DOI: 10.1016/j.cels.2025.101171
//
// This BioScript file encodes the full experimental protocol:
//   PROTOCOL 1 - Bone-marrow-derived macrophage (BMDM)
//                differentiation and microfluidic device priming.
//   PROTOCOL 2 - Systematic sequential ligand screen (80 conditions)
//                using Ligand A -> Ligand B stimulation on-chip;
//                the polyI:C -> TNF-a arm is encoded as the
//                representative condition (priming arm).
//                The CpG -> TNF-a arm is encoded in parallel
//                (tolerance arm).
//   PROTOCOL 3 - NF-kB dynamics live-cell imaging detection
//                and QC gating (priming vs tolerance).
//   PROTOCOL 4 - ATAC-seq chromatin accessibility profiling
//                following single and sequential stimulation.
//   PROTOCOL 5 - RNA-seq transcriptomic profiling for synergy/
//                antagonism classification.
//
// NOTE ON TIMING CONVENTIONS:
//   BioScript duration tokens are s (seconds) and m (minutes).
//   Hours are converted to minutes (e.g., 4h = 240m, 8h = 480m,
//   48h = 2880m, 7 days = 10080m).
//
// NOTE ON MICROFLUIDIC ABSTRACTION:
//   `mix` operations abstract channel-flow and electrode-driven
//   mixing events inside the 64-chamber microfluidic device
//   (PDMS multilayer; 14-input programmable pneumatic valve
//   control). No DMF electrode merging is implied.
//   `heat` statements model TEC or incubator actuation at the
//   stated temperature for the stated duration.
//
// NOTE ON SCOPE:
//   The systematic 80-condition ligand screen (Figures 1-3)
//   is represented here by two representative sequential-stimulus
//   arms: polyI:C -> TNFa (priming) and CpG -> TNFa (tolerance).
//   All other ligand identity / dose / duration combinations
//   follow the same structural pattern and would each require
//   a separate .bs file or parameterised extension.
//
// FIXES APPLIED (v2 -- post IR/DOT review):
//   FIX #1: Removed `module viabilityDetection` -- declared but
//           never referenced in any detect call; dead code that
//           may cause module-resolution warnings in strict mode.
//   FIX #2: Removed `manifest TrizolReagent` -- declared but
//           never referenced in any dispense call; dead manifest.
//   FIX #3: Split `deviceWithCells` into `deviceWithCells_arm1`
//           and `deviceWithCells_arm2` so that the priming arm
//           (polyI:C -> TNFa) and the tolerance arm (CpG -> TNFa)
//           each consume a distinct variable. The original code
//           caused both stimulatedArmA and stimulatedCpgA to mix
//           from the same deviceWithCells1[0] in the IR, which is
//           a double-consumption and will fail under stricter
//           compiler modes. Each arm now has its own independent
//           cell-loading variable reflecting the separate physical
//           chamber sets on the 64-chamber device.
//
// CFG STRUCTURE:
//   BB1  main                -- BMDM differentiation, device priming,
//                               cell loading
//   BB2  primingPass         -- nfkbPrimingSignal > 0: priming detected
//                               (polyI:C -> TNFa); dispose and continue
//   BB3  primingFail         -- nfkbPrimingSignal <= 0: no priming;
//                               drain stimulated cells
//   BB4  stimJoin            -- join: ATAC-seq branch begins
//   BB5  atacPass            -- atacSignal > 0: valid accessible
//                               chromatin peaks; dispose and continue
//   BB6  atacFail            -- atacSignal <= 0: library prep failed;
//                               drain nuclei lysate
//   BB7  atacJoin            -- join: RNA-seq branch begins
//   BB8  rnaSeqPass          -- rnaSignal > 0: valid transcriptomic
//                               data; dispose and end
//   BB9  rnaSeqFail          -- rnaSignal <= 0: low-quality library;
//                               drain RNA lysate
//   BB10 finalCleanup        -- terminal: dispose all QC signals
// ============================================================

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 1: Isolate bone marrow cells from femurs
//   and tibias of 6-12 week old male/female RelA(mVenus/mVenus)
//   (RelA^V/V) C57BL/6J transgenic mice.
//   Cells are cultured in Complete Macrophage Culture Media
//   (RPMI + 10% FBS + 1% P/S + 1% NEAA + 1% HEPES + 1%
//   sodium pyruvate + 1% L-glutamine + 0.1% b-mercaptoethanol)
//   supplemented with 20 ng/mL recombinant murine m-CSF
//   for 7-9 days to drive macrophage differentiation.
//   Fed on Days 2, 4, and 6 with fresh supplemented media.
//   7-9 day differentiation = 10080-12960 min. 7 days used here.
// ------------------------------------------------------------

boneMarrow      = dispense 1 units of BoneMarrowCells
baseMCM         = dispense 1 units of CompleteMCM
mcsf1           = dispense 1 units of MCSF

// Initial culture seeding
cultureMedia_D0 = mix baseMCM with mcsf1 for 5s
seededCulture   = mix boneMarrow with cultureMedia_D0 for 2m

// Day 2 feed
mcm_D2          = dispense 1 units of CompleteMCM
mcsf_D2         = dispense 1 units of MCSF
feed_D2         = mix mcm_D2 with mcsf_D2 for 5s
culture_D2      = mix seededCulture with feed_D2 for 2880m

// Day 4 feed
mcm_D4          = dispense 1 units of CompleteMCM
mcsf_D4         = dispense 1 units of MCSF
feed_D4         = mix mcm_D4 with mcsf_D4 for 5s
culture_D4      = mix culture_D2 with feed_D4 for 2880m

// Day 6 feed
mcm_D6          = dispense 1 units of CompleteMCM
mcsf_D6         = dispense 1 units of MCSF
feed_D6         = mix mcm_D6 with mcsf_D6 for 5s
culture_D6      = mix culture_D4 with feed_D6 for 2880m

// Day 7-9: lift adherent BMDMs with 10 mM EDTA in PBS,
// wash and resuspend at 10^7 cells/mL in phenol-red-free RPMI
// for loading into microfluidic device. Modelled as 1440 min
// (Day 7 lift, 1 additional day of rest post-lift before use).
lift_PBS        = dispense 1 units of PBS
matureBMDMs     = mix culture_D6 with lift_PBS for 1440m

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 2: Microfluidic device preparation.
//   PDMS multilayer device (64 cell-culture chambers, 14 inputs).
//   Coat chambers overnight with 0.2-0.4 mg/mL fibronectin in
//   PBS to promote cell adhesion. Flush with complete media.
//   Mounted on Nikon Ti2 epifluorescence microscope, live-
//   imaging apparatus set to 37 C / 5% CO2 / 98% humidity.
//   `mix` abstracts fibronectin coating and chamber flush.
// ------------------------------------------------------------

fibronectinSoln  = dispense 1 units of Fibronectin
primingPBS       = dispense 1 units of PBS
deviceCoating    = mix fibronectinSoln with primingPBS for 480m

flushMedia       = dispense 1 units of CompleteMCM
devicePrimed     = mix deviceCoating with flushMedia for 10m

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 3: Load BMDMs onto microfluidic device.
//   Cells loaded at 10^7/mL in phenol-red-free RPMI. Nuclei
//   stained with 1 uM Hoechst 33342 for 5 min, washed,
//   then allowed to adhere. Imaged at 6-min intervals,
//   20x magnification (mVenus: 508 nm, 1 s; Hoechst: 395 nm,
//   50 ms; Hamamatsu ORCA-Flash4.0 V2 camera).
// ------------------------------------------------------------

hoechstStain     = dispense 1 units of HoechstStain
stainedBMDMs     = mix matureBMDMs with hoechstStain for 5m

washPBS          = dispense 1 units of PBS
loadedCells      = mix stainedBMDMs with washPBS for 2s

// FIX #3: Split into two independent device-with-cells variables
// so that Arm 1 (polyI:C -> TNFa) and Arm 2 (CpG -> TNFa) each
// consume a distinct variable. Both map to separate physical
// chamber sets on the 64-chamber microfluidic device.
// Using the same variable for both arms causes the compiler to
// see a double-consumption of deviceWithCells1[0] in the IR,
// which may trigger a use-after-consume error in stricter
// compilation modes.
deviceWithCells_arm1 = mix loadedCells with devicePrimed for 30m

// Arm 2 requires an independent device loading from the same
// cell and device preparation. Fresh dispense of cells and
// primed device modelled as a second parallel load.
loadedCells2         = dispense 1 units of BoneMarrowCells
devicePrimed2        = dispense 1 units of Fibronectin
deviceWithCells_arm2 = mix loadedCells2 with devicePrimed2 for 30m

// ============================================================
// PROTOCOL 2 - Sequential Ligand Stimulation Screen
// Representative Arm 1: polyI:C -> TNF-a (PRIMING arm)
//   polyI:C activates TLR3/TRIF pathway; primes NF-kB response
//   to subsequent TNF-a stimulation.
//   Ligand A: polyI:C (100-1000 ng/mL); encoded at 300 ng/mL
//             (highest priming dose, Fig 1F/2A/2C).
//             Duration: 4 hours (240 min) of Ligand A.
//   Ligand B: TNF-a (10 ng/mL); duration 4 hours (240 min).
//   Total imaging window: 480 min per cell condition.
//   >300 individual cells tracked per condition.
// ============================================================

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 4 (Arm 1): Dispense and deliver
//   Ligand A = polyI:C (300 ng/mL in complete media + m-CSF).
//   Delivered via PEEK tubing at 4 psi to minimise shearing.
//   Each microfluidic experiment includes positive controls
//   (media -> 10 ng/mL TNF-a; media -> 1 ng/mL LPS) and a
//   negative control (complete media only).
// ------------------------------------------------------------

polyIC_LigA      = dispense 1 units of PolyIC
mcm_LigA         = dispense 1 units of CompleteMCM
polyIC_Stimulus  = mix polyIC_LigA with mcm_LigA for 5s

// Stimulate cells with polyI:C for 4 h (240 min) on-chip.
// `mix` abstracts pneumatic valve-driven channel perfusion.
stimulatedArmA   = mix deviceWithCells_arm1 with polyIC_Stimulus for 240m

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 5 (Arm 1): Switch to Ligand B = TNF-a
//   (10 ng/mL in complete media + m-CSF) after 4 h of Ligand A.
//   Ligand A is aspirated; Ligand B delivered via same channel.
//   NF-kB nuclear translocation (RelA-mVenus nuclear/cytoplasmic
//   ratio) tracked during the entire Ligand B window (240 min).
// ------------------------------------------------------------

TNFa_LigB        = dispense 1 units of TNFa
mcm_LigB         = dispense 1 units of CompleteMCM
TNFa_Stimulus    = mix TNFa_LigB with mcm_LigB for 5s

// Stimulate with TNF-a for 4 h (240 min) post-polyI:C.
stimulatedArmB   = mix stimulatedArmA with TNFa_Stimulus for 240m

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 6 (Arm 2): CpG -> TNF-a (TOLERANCE arm)
//   CpG activates TLR9/MyD88 pathway; tolerises NF-kB response
//   to subsequent TNF-a stimulation.
//   Ligand A: CpG (100 nM = highest tolerising dose; Fig 1E).
//   Duration: 4 hours (240 min).
//   Ligand B: TNF-a (10 ng/mL); duration 4 hours (240 min).
//   Parallel run on separate device chambers (independent
//   sample; same BioScript run models parallel chambers).
// ------------------------------------------------------------

CpG_LigA         = dispense 1 units of CpG
mcm_CpG          = dispense 1 units of CompleteMCM
CpG_Stimulus     = mix CpG_LigA with mcm_CpG for 5s

// Arm 2 now consumes deviceWithCells_arm2 (not arm1).
stimulatedCpgA   = mix deviceWithCells_arm2 with CpG_Stimulus for 240m

TNFa_LigB2       = dispense 1 units of TNFa
mcm_LigB2        = dispense 1 units of CompleteMCM
TNFa_Stimulus2   = mix TNFa_LigB2 with mcm_LigB2 for 5s

stimulatedCpgB   = mix stimulatedCpgA with TNFa_Stimulus2 for 240m

// ------------------------------------------------------------
// PROTOCOL 3 - STEP 7: Live-cell NF-kB dynamics detection.
//   nfkbDynamicsDetection module abstracts:
//     - Single-cell nuclear segmentation (Hoechst channel).
//     - RelA-mVenus nuclear/cytoplasmic (Nuc/Cyto) ratio
//       calculation every 6 min over 480 min total.
//     - AUC (trapezoidal) and maximum amplitude extraction.
//     - Normalisation to naive Ligand B AUC (AUC_0).
//     - Mutual information analysis (20-point dynamic vector)
//       using Jetka et al. (2019) PLOS Comp Biol method.
//   QC gate: normalised AUC > 1 = priming; < 1 = tolerance.
//   >300 cells per condition; two independent preparations.
// ------------------------------------------------------------

// Detect NF-kB dynamics for the priming arm (polyI:C -> TNFa).
nfkbPrimingSignal = detect nfkbDynamicsDetection on stimulatedArmB for 240m

// Detect NF-kB dynamics for the tolerance arm (CpG -> TNFa).
nfkbToleranceSignal = detect nfkbDynamicsDetection on stimulatedCpgB for 240m

// ============================================================
// BB2 / BB3: NF-kB dynamics QC gate (priming arm)
// Pass (BB2): nfkbPrimingSignal > 0 -> priming confirmed
//             (normalised AUC > naive); dispose stimulated cells.
// Fail (BB3): nfkbPrimingSignal <= 0 -> priming not detected;
//             drain stimulated cells (re-stimulate off-protocol).
// Both branches converge at BB4 (stimJoin).
// ============================================================

if (nfkbPrimingSignal > 0) {
    dispose stimulatedArmB
} else {
    drain stimulatedArmB
}

// Dispose tolerance arm stimulated cells after detection
// (tolerance QC is encoded implicitly; CpG data used in
// ATAC/RNA-seq branches below regardless of NF-kB outcome
// as paper uses four representative conditions for seq.)
dispose stimulatedCpgB

// ============================================================
// BB4: stimJoin
// Dispose NF-kB QC signal droplets. Control falls into
// ATAC-seq chromatin accessibility profiling branch.
// ============================================================

dispose nfkbPrimingSignal
dispose nfkbToleranceSignal

// ============================================================
// PROTOCOL 4 - ATAC-seq Chromatin Accessibility Profiling
//   BMDMs replated at 7.5e5 cells/well in 6-well plates (Day 7).
//   Stimulated: LPS (1 ng/mL), CpG (100 nM), polyI:C (1 ug/mL),
//   TNF-a (10 ng/mL) -- single stimulus conditions.
//   Sequential: polyI:C/CpG -> TNF-a/LPS (4 h each).
//   Cells lifted with Accutase + gentle scraping; 5e4 cells used.
//   ATAC performed using Buenrostro et al. (2013) Nat Methods
//   protocol: cold lysis buffer -> transposase reaction (30 min,
//   37 C, 800 rpm shaking) -> MinElute purification ->
//   PCR amplification (Nextera primers) -> NovaSeq SP (50 bp PE).
//   Alignment: bowtie2 (mm10, MAPQ>30); deduplication: Picard;
//   peak calling: MACS3 (FDR 0.01, BAMPE, mm genome, nomodel);
//   motif enrichment: monaLisa / JASPAR2022.
//
// Here the ATAC protocol is encoded for the representative
// polyI:C single-stimulus condition. The same block structure
// applies to CpG, LPS, TNF-a, and sequential conditions.
// ============================================================

// ------------------------------------------------------------
// PROTOCOL 4 - STEP 8: Plate BMDMs for ATAC-seq.
//   Fresh matureBMDMs dispense into well plates for replating.
//   Overnight rest in complete media + m-CSF before stimulation.
// ------------------------------------------------------------

atacBMDMs        = dispense 1 units of BoneMarrowCells
atacMedia        = dispense 1 units of CompleteMCM
atacMCSF         = dispense 1 units of MCSF
atacCultureMix   = mix atacMedia with atacMCSF for 5s
atacPlated       = mix atacBMDMs with atacCultureMix for 480m

// ------------------------------------------------------------
// PROTOCOL 4 - STEP 9: Single-stimulus ATAC-seq condition.
//   polyI:C (1 ug/mL) for 4 h (240 min). One representative
//   condition; paper runs all six ligands in parallel.
// ------------------------------------------------------------

polyIC_ATAC      = dispense 1 units of PolyIC
atacMediaPIC     = dispense 1 units of CompleteMCM
polyIC_ATACStim  = mix polyIC_ATAC with atacMediaPIC for 5s

atacStimulated   = mix atacPlated with polyIC_ATACStim for 240m

// ------------------------------------------------------------
// PROTOCOL 4 - STEP 10: Cell lysis and nuclei isolation.
//   Cells lifted with Accutase (ThermoFisher) + gentle scraping.
//   5e4 cells pelleted; lysed in cold lysis buffer
//   (10 mM Tris-HCl pH 7.5, 3 mM MgCl2, 10 mM NaCl,
//   0.1% IGEPAL CA-630). Centrifuge 10 min, 500 x g.
//   `mix` abstracts Accutase lift, lysis, and centrifugation.
// ------------------------------------------------------------

accutase         = dispense 1 units of Accutase
liftedCells      = mix atacStimulated with accutase for 5m

lysisBuffer      = dispense 1 units of PBS
// PBS here abstracts the cold lysis buffer composition.
// lysis on ice for 3 min (cold step modelled as 4 C, 3 min).
nucleiLysate     = mix liftedCells with lysisBuffer for 3m
heat nucleiLysate at 4c for 10m

// ------------------------------------------------------------
// PROTOCOL 4 - STEP 11: Transposase reaction.
//   Nuclei resuspended in transposase mix (25 uL 2X TD Buffer
//   + 2.5 uL TD Enzyme 1 [Illumina] + 22.5 uL nuclease-free
//   water). Incubated 30 min at 37 C, 800 rpm shaker.
//   Abstracted as heat at 37 C for 30 min.
// ------------------------------------------------------------

transposaseMix   = dispense 1 units of TransposaseReactionMix
tagmentedDNA     = mix nucleiLysate with transposaseMix for 5s
heat tagmentedDNA at 37c for 30m

// ------------------------------------------------------------
// PROTOCOL 4 - STEP 12: PCR amplification and library prep.
//   Purified with MinElute kit (Qiagen). Amplified with Nextera
//   XT sequencing primers. Libraries pooled and sequenced on
//   Illumina NovaSeq SP (50 bp paired-end).
//   Modelled as mix (primer addition) + heat (PCR cycles).
//   PCR: 72 C 5 min initial extension, then 98 C 30s /
//   63 C 30s / 72 C 1 min for n cycles. 12 cycles typical.
//   Simplified here as 37c (post-PCR hold) for 30m.
// ------------------------------------------------------------

atacPrimers      = dispense 1 units of ATACLibraryPrimers
atacLibrary      = mix tagmentedDNA with atacPrimers for 5s
heat atacLibrary at 72c for 30m

// ATAC-seq detection: atacSeqDetection module abstracts
// bowtie2 alignment, MACS3 peak calling, monaLisa motif
// enrichment, and edgeR/limma differential accessibility.
// QC: detects valid open chromatin peaks above noise.
atacSignal       = detect atacSeqDetection on atacLibrary for 30s

// ============================================================
// BB5 / BB6: ATAC-seq QC gate
// Pass (BB5): atacSignal > 0 -> valid chromatin accessibility
//             peaks detected; dispose library and continue.
// Fail (BB6): atacSignal <= 0 -> library prep failed (low
//             signal-to-noise or alignment failure); drain.
// Both branches converge at BB7 (atacJoin).
// ============================================================

if (atacSignal > 0) {
    dispose atacLibrary
} else {
    drain atacLibrary
}

// ============================================================
// BB7: atacJoin
// Dispose ATAC-seq QC signal. Control falls into RNA-seq
// transcriptomic profiling branch.
// ============================================================

dispose atacSignal

// ============================================================
// PROTOCOL 5 - RNA-seq Transcriptomic Profiling
//   BMDMs replated at 1.5e5 cells/well in 24-well plates.
//   Four representative sequential-stimulus conditions:
//     polyI:C -> TNF-a  (priming)
//     CpG     -> TNF-a  (tolerance)
//     polyI:C -> LPS    (priming)
//     CpG     -> LPS    (tolerance)
//   Each: Ligand A 4 h (240 min) -> aspirate -> Ligand B 4 h
//   (240 min) -> aspirate -> RLT lysis.
//   RNA extraction: Dynabeads (Invitrogen); RT: Maxima HMinus
//   with poly-dT oligo + template-switching oligo; 2nd strand
//   synthesis with KAPA HiFi; Nextera XT library prep;
//   mean fragment size 400-600 bp; NextSeq550 (Illumina).
//   Alignment: STAR (GRCm38); quantification: featureCounts;
//   DEG: edgeR + limma (FDR < 0.01, FC > 1 vs naive).
//   Synergy/antagonism: DAB_memory formula vs null hypothesis.
//
// Encoded here: polyI:C -> TNF-a arm as representative.
// ============================================================

// ------------------------------------------------------------
// PROTOCOL 5 - STEP 13: Plate BMDMs for RNA-seq.
//   Overnight rest in 24-well plate, complete media + m-CSF.
// ------------------------------------------------------------

rnaBMDMs         = dispense 1 units of BoneMarrowCells
rnaMedia         = dispense 1 units of CompleteMCM
rnaMCSF          = dispense 1 units of MCSF
rnaCultureMix    = mix rnaMedia with rnaMCSF for 5s
rnaPlated        = mix rnaBMDMs with rnaCultureMix for 480m

// ------------------------------------------------------------
// PROTOCOL 5 - STEP 14: Stimulus A application (polyI:C,
//   4 h at 37 C, 5% CO2).
// ------------------------------------------------------------

polyIC_RNA       = dispense 1 units of PolyIC
rnaMediaA        = dispense 1 units of CompleteMCM
polyIC_RNAStim   = mix polyIC_RNA with rnaMediaA for 5s
rnaStimA         = mix rnaPlated with polyIC_RNAStim for 240m

// ------------------------------------------------------------
// PROTOCOL 5 - STEP 15: Aspirate Ligand A; apply Ligand B
//   (TNF-a, 10 ng/mL in complete media + m-CSF) for 4 h.
// ------------------------------------------------------------

TNFa_RNA         = dispense 1 units of TNFa
rnaMediaB        = dispense 1 units of CompleteMCM
TNFa_RNAStim     = mix TNFa_RNA with rnaMediaB for 5s
rnaStimB         = mix rnaStimA with TNFa_RNAStim for 240m

// ------------------------------------------------------------
// PROTOCOL 5 - STEP 16: Cell lysis and RNA extraction.
//   Aspirate Ligand B; lyse cells in RLT buffer + 1%
//   b-mercaptoethanol. RNA extracted using Dynabeads.
// ------------------------------------------------------------

rltBuffer        = dispense 1 units of RLT_Buffer
rnaLysate        = mix rnaStimB with rltBuffer for 5m

// ------------------------------------------------------------
// PROTOCOL 5 - STEP 17: Reverse transcription and library prep.
//   RT with Maxima HMinus + poly-dT oligo + TSO.
//   2nd strand with KAPA HiFi.
//   Nextera XT library preparation; NextSeq550 sequencing.
//   Modelled as heat (RT step: 55 C for 60 min).
// ------------------------------------------------------------

nextXTKit        = dispense 1 units of NexteraXTKit
rnaLibrary       = mix rnaLysate with nextXTKit for 60m
heat rnaLibrary at 55c for 60m

// RNA-seq detection: rnaSeqDetection module abstracts
// STAR alignment, featureCounts quantification, edgeR/limma
// DE analysis, and synergy/antagonism classification using
// DAB_memory formula (threshold: +/-25% vs null hypothesis).
// QC: detects valid mapped library with adequate read depth.
rnaSignal        = detect rnaSeqDetection on rnaLibrary for 30s

// ============================================================
// BB8 / BB9: RNA-seq QC gate
// Pass (BB8): rnaSignal > 0 -> valid transcriptomic library
//             detected (adequate read depth, alignment rate);
//             dispose library, proceed to final cleanup.
// Fail (BB9): rnaSignal <= 0 -> degraded RNA or library
//             failure (low RIN or low mapping rate); drain.
// Both branches converge at BB10 (finalCleanup).
// ============================================================

if (rnaSignal > 0) {
    dispose rnaLibrary
} else {
    drain rnaLibrary
}

// ============================================================
// BB10: finalCleanup (terminal)
// Dispose all remaining QC signal variables.
// Experiment ends.
// ============================================================

dispose rnaSignal

// [terminal -- no further instructions; exit node for CFG]

module fluorescence

manifest whole_blood
manifest reconstitution_solvent
manifest anti_A
manifest anti_B
manifest anti_AB
manifest anti_D
manifest hematocrit_reagent

instructions:

// Step 1: reconstitute the lyophilized (dried) blood-typing antibodies
// and the chemical agglutination agent used for hematocrit
solvent_a = dispense 1 units of reconstitution_solvent
solvent_b = dispense 1 units of reconstitution_solvent
solvent_ab = dispense 1 units of reconstitution_solvent
solvent_d = dispense 1 units of reconstitution_solvent
solvent_hct = dispense 1 units of reconstitution_solvent

dry_a = dispense 1 units of anti_A
dry_b = dispense 1 units of anti_B
dry_ab = dispense 1 units of anti_AB
dry_d = dispense 1 units of anti_D
dry_hct = dispense 1 units of hematocrit_reagent

reagent_a = mix solvent_a with dry_a for 5s
reagent_b = mix solvent_b with dry_b for 5s
reagent_ab = mix solvent_ab with dry_ab for 5s
reagent_d = mix solvent_d with dry_d for 5s
reagent_hct = mix solvent_hct with dry_hct for 5s

// Step 2: meter whole-blood unit-droplets for each parallel test
blood_a = dispense 1 units of whole_blood
blood_b = dispense 1 units of whole_blood
blood_ab = dispense 1 units of whole_blood
blood_d = dispense 1 units of whole_blood
blood_hct = dispense 1 units of whole_blood

// Step 3: merge each blood droplet with its reconstituted reagent
// and mix to form the double-unit product droplet
test_a = mix blood_a with reagent_a for 10s
test_b = mix blood_b with reagent_b for 10s
test_ab = mix blood_ab with reagent_ab for 10s
test_d = mix blood_d with reagent_d for 10s
test_hct = mix blood_hct with reagent_hct for 10s

// Step 4: DAAD imaging read-out of agglutination state for the
// ABO/RhD blood-typing panel (anti-A, anti-B, anti-AB, anti-D)
score_a = detect fluorescence on test_a for 5s
score_b = detect fluorescence on test_b for 5s
score_ab = detect fluorescence on test_ab for 5s
score_d = detect fluorescence on test_d for 5s

// Below-threshold scores correspond to nonagglutinated (negative) droplets
if (score_a <= 15) {
    dispose test_a
}

if (score_b <= 15) {
    dispose test_b
}

if (score_ab <= 15) {
    dispose test_ab
}

if (score_d <= 15) {
    dispose test_d
}

// Step 5: quantitative DAAD hematocrit scoring on the chemically
// agglutinated blood droplet
hct_score = detect fluorescence on test_hct for 5s

if (hct_score <= 15) {
    dispose test_hct
}

// Step 6: clear remaining (agglutinated/positive) droplets from the array
dispose test_a
dispose test_b
dispose test_ab
dispose test_d
dispose test_hct

module eclDetection

manifest MagneticParticles
manifest TargetSequence
manifest HybridizationBuffer
manifest RuPhen3Cl2
manifest PBS
manifest TPA
manifest PluronicF68

instructions:

// ============================================================
// Electrochemiluminescence on Digital Microfluidics for
// microRNA Analysis
// Shamsi, Choi, Ng, Chamberlain, Wheeler
// Biosensors and Bioelectronics, 2015
// DOI: 10.1016/j.bios.2015.10.036
//
// Protocol: Magnetic particle-based oligonucleotide
// hybridization assay on DMF coupled to ECL detection.
// miRNA-143 (ds-143) is captured by ss-143-modified
// Dynabeads M-280 Streptavidin and detected via
// [Ru(Phen)3]Cl2 intercalation and TPA co-reactant
// at ITO working electrodes on the DMF top-plate.
//
// REAGENT NOTES:
//   MagneticParticles: 4.5 uL aliquots of Dynabeads M-280
//     Streptavidin (10 mg/mL, ~6-7e8 particles/mL in PBS,
//     0.1% BSA, 0.02% NaN3) pre-coated with ss-143 probe
//     DNA via avidin-biotin chemistry. All solutions
//     supplemented with 0.05% Pluronics F68 v/v.
//   TargetSequence: ds-143 in hybridization buffer (0, 10,
//     100, or 1000 nM). For cell lysate assays, MCF-7 or
//     MDA-MB-231 lysate diluted 1:10 in sample dilution
//     buffer (pH 8.0, Tris-base 7.7 mM, Tris-HCl 12.2 mM,
//     NaCl 200 mM, MgCl2 5 mM, BSA 4% w/v, Pluronic L64
//     0.05% w/v).
//   HybridizationBuffer: 20 mM Tris-HCl, 0.2 M NaCl,
//     5 mM MgCl2, pH 8.0.
//   RuPhen3Cl2: 200 uM [Ru(Phen)3]Cl2 in PBS (1x), pH 7.5.
//   PBS: phosphate buffered saline (1x), pH 7.5.
//   TPA: 20 mM tripropylamine in PBS (1x), pH 7.5.
//   PluronicF68: 0.05% v/v in all above solutions.
//
// ECL DETECTION NOTE:
//   eclDetection module abstracts the ITO working electrode
//   (WE, 800 um dia.) and Ag/Au/ITO counter/pseudoreference
//   (CE/RE, 560 um x 560 um) on the DMF top-plate. 1.5 V
//   DC applied for 45 s; maximum ECL photon count recorded
//   within the first 10 s via PMT (CV ~10%).
//   Ru(Phen)3(2+) intercalates dsDNA (4 bp per ion); signal
//   is proportional to hybridized ds-143 captured on beads.
//   LOD: 1.1 nM (CLOD), 1.5 femtomoles (absolute). Total
//   assay time: ~40 min for two parallel assays.
//
// MAGNETIC SEPARATION NOTE:
//   All `heat` steps marked "magnet" abstract the permanent
//   magnet positioned below the DMF bottom plate to
//   immobilize Dynabeads while the supernatant droplet is
//   transported away by electrode actuation. The temperature
//   parameter (25c) reflects ambient/room temperature;
//   no thermal effect is intended at these steps.
//
// PRE-ASSAY STEP (off-chip, not encoded in BioScript):
//   Cathodic electrochemical cleaning of ITO WEs:
//   cyclic voltammetry in 20 uL PBS (1x) on DMF top-plate,
//   10 cycles from -1 V to 0 V at 100 mV/s using ITO WE
//   and Ag/Au/ITO CE/RE.
//
// CFG STRUCTURE:
//   BB1  main              -- entry: particle dispense and
//                             magnetic separation; target
//                             hybridization; wash x4;
//                             Ru(Phen)3 labeling; wash x2;
//                             TPA addition; ECL detection
//   BB2  eclPass           -- eclSignal > 0: valid ECL above
//                             blank; dispose final droplet
//   BB3  eclFail           -- eclSignal <= 0: no signal
//                             (below LOD or reagent failure);
//                             drain final droplet
//   BB4  finalCleanup      -- terminal: dispose ECL signal
// ============================================================

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Dispense magnetic particle droplets and merge.
//   Paper M&M Sec 2.3: "three unit droplets containing
//   magnetic particles were dispensed from their reservoir
//   and merged." (For cell lysate assays, five unit droplets
//   were used instead of three; three used here for the
//   standard synthetic target protocol.)
//   Each unit droplet ~1.8 uL; three merged = ~5.4 uL total.
// ------------------------------------------------------------

beads1 = dispense 1 units of MagneticParticles
beads2 = dispense 1 units of MagneticParticles
beads3 = dispense 1 units of MagneticParticles

beadsMerge1 = mix beads1 with beads2 for 5s
beadsMerged = mix beadsMerge1 with beads3 for 5s

// ------------------------------------------------------------
// STEP 2: Magnetic separation - pellet beads, remove
//   supernatant (storage buffer). Magnet applied below device;
//   supernatant droplet actuated away from bead pellet.
//   `heat` at 25c for 30s abstracts magnet hold time.
// ------------------------------------------------------------

heat beadsMerged at 25c for 30s
dispose beadsMerged

// ------------------------------------------------------------
// STEP 3: Dispense target sequence droplets and merge.
//   Paper M&M Sec 2.3: "two unit droplets of target sequence
//   solution were dispensed, merged, and delivered to the
//   immobilized particles for resuspension and incubation
//   for 15 min."
//   TargetSequence reservoir: ds-143 in hybridization buffer
//   at test concentration (10/100/1000 nM) or cell lysate.
// ------------------------------------------------------------

target1 = dispense 1 units of TargetSequence
target2 = dispense 1 units of TargetSequence

targetMerged = mix target1 with target2 for 5s

// ------------------------------------------------------------
// STEP 4: Hybridization incubation.
//   Deliver merged target droplet to bead pellet; resuspend
//   by electrode actuation (mixing) and incubate for 15 min.
//   ds-143 hybridizes to ss-143 immobilized on beads.
//   `mix` abstracts both resuspension and incubation; the
//   15m duration encodes the hybridization dwell time.
//
//   NOTE: beadsMerged was disposed after magnetic separation
//   (step 2). The bead pellet physically remains on-device
//   at the electrode; targetMerged is merged with a freshly
//   dispensed bead pellet representation. In BioScript,
//   re-dispense from MagneticParticles models the pellet
//   being resuspended by the incoming target droplet, which
//   is the physical reality of the protocol (the magnet is
//   removed and electrode actuation drives resuspension).
// ------------------------------------------------------------

pelletForHybrid = dispense 1 units of MagneticParticles
hybridDroplet   = mix pelletForHybrid with targetMerged for 15m

// ------------------------------------------------------------
// STEP 5: Magnetic separation - remove unbound target.
//   Magnet applied; beads pellet; supernatant (unbound ds-143)
//   actuated away. `heat` at 25c for 30s = magnet hold.
// ------------------------------------------------------------

heat hybridDroplet at 25c for 30s
dispose hybridDroplet

// ------------------------------------------------------------
// STEP 6: Wash cycle x4 (hybridization buffer).
//   Paper M&M Sec 2.3: "particles were washed four times in
//   series by re-suspending and mixing with one unit droplet
//   of hybridization buffer followed by magnetic separation
//   from the supernatant."
//   Each wash: dispense 1 unit HybridizationBuffer, mix 1m
//   to resuspend beads, apply magnet 30s, dispose supernatant.
//   Four serial wash cycles encoded explicitly below.
//
//   As in STEP 4, pellet re-dispense from MagneticParticles
//   models the retained bead pellet at each wash cycle.
// ------------------------------------------------------------

// Wash 1
pelletW1   = dispense 1 units of MagneticParticles
washBuf1   = dispense 1 units of HybridizationBuffer
washMix1   = mix pelletW1 with washBuf1 for 1m
heat washMix1 at 25c for 30s
dispose washMix1

// Wash 2
pelletW2   = dispense 1 units of MagneticParticles
washBuf2   = dispense 1 units of HybridizationBuffer
washMix2   = mix pelletW2 with washBuf2 for 1m
heat washMix2 at 25c for 30s
dispose washMix2

// Wash 3
pelletW3   = dispense 1 units of MagneticParticles
washBuf3   = dispense 1 units of HybridizationBuffer
washMix3   = mix pelletW3 with washBuf3 for 1m
heat washMix3 at 25c for 30s
dispose washMix3

// Wash 4
pelletW4   = dispense 1 units of MagneticParticles
washBuf4   = dispense 1 units of HybridizationBuffer
washMix4   = mix pelletW4 with washBuf4 for 1m
heat washMix4 at 25c for 30s
dispose washMix4

// ------------------------------------------------------------
// STEP 7: [Ru(Phen)3]Cl2 intercalation labeling.
//   Paper M&M Sec 2.3: "two unit droplets of [Ru(Phen)3]Cl2
//   solution were dispensed, merged, and delivered to the
//   particles, where they were re-suspended and mixed for
//   2 min. The particles were then separated from the
//   supernatant droplet."
//   Ru(Phen)3(2+) intercalates into dsDNA (4 bp per ion);
//   does not bind ssDNA or RNA. Signal is proportional to
//   amount of hybridized ds-143 on bead surface.
// ------------------------------------------------------------

pelletForRu  = dispense 1 units of MagneticParticles
ruDrop1      = dispense 1 units of RuPhen3Cl2
ruDrop2      = dispense 1 units of RuPhen3Cl2

ruMerged     = mix ruDrop1 with ruDrop2 for 5s
ruLabelMix   = mix pelletForRu with ruMerged for 2m

// Magnetic separation: remove unbound Ru(Phen)3(2+).
heat ruLabelMix at 25c for 30s
dispose ruLabelMix

// ------------------------------------------------------------
// STEP 8: PBS wash x2 (remove excess Ru(Phen)3(2+)).
//   Paper M&M Sec 2.3: "particles were washed two times with
//   2 droplets of PBS as in step 3."
//   Each wash: 1 unit PBS, mix 1m, magnet 30s, dispose.
// ------------------------------------------------------------

// PBS Wash 1
pelletPW1  = dispense 1 units of MagneticParticles
pbsWash1   = dispense 1 units of PBS
pbsMix1    = mix pelletPW1 with pbsWash1 for 1m
heat pbsMix1 at 25c for 30s
dispose pbsMix1

// PBS Wash 2
pelletPW2  = dispense 1 units of MagneticParticles
pbsWash2   = dispense 1 units of PBS
pbsMix2    = mix pelletPW2 with pbsWash2 for 1m
heat pbsMix2 at 25c for 30s
dispose pbsMix2

// ------------------------------------------------------------
// STEP 9: TPA co-reactant addition.
//   Paper M&M Sec 2.3: "two droplets of TPA solution were
//   dispensed, merged, and delivered to the particles, where
//   they were re-suspended and mixed for 1 min."
//   TPA (tripropylamine) is the ECL co-reactant; oxidized
//   simultaneously with Ru(Phen)3(2+) at the ITO WE.
//   The TPA(+) radical reduces the luminophore to the
//   excited state that emits at ~610 nm.
// ------------------------------------------------------------

pelletForTPA = dispense 1 units of MagneticParticles
tpaDrop1     = dispense 1 units of TPA
tpaDrop2     = dispense 1 units of TPA

tpaMerged    = mix tpaDrop1 with tpaDrop2 for 5s
finalDroplet = mix pelletForTPA with tpaMerged for 1m

// ------------------------------------------------------------
// STEP 10: ECL measurement.
//   Paper M&M Sec 2.3: "the final droplet containing TPA and
//   Ru(Phen)3(2+)-labeled DNA modified particles was actuated
//   to the ECL electrodes on the top-plate for ECL
//   measurements."
//   1.5 V DC applied between ITO WE and Ag/Au/ITO CE/RE
//   for 45 s. Maximum ECL counts recorded within first 10 s.
//   eclDetection module abstracts the PMT readout.
//   LOD: CLOD = 1.1 nM; absolute LOD = 1.5 femtomoles.
// ------------------------------------------------------------

eclSignal = detect eclDetection on finalDroplet for 45s

// ============================================================
// BB2 / BB3: ECL QC gate
// Pass (BB2): eclSignal > 0 -> ECL counts above blank
//             (hybridization detected); dispose final droplet.
// Fail (BB3): eclSignal <= 0 -> signal at or below blank
//             (no hybridization or below LOD); drain.
// Both branches converge at BB4 (finalCleanup).
// ============================================================

if (eclSignal > 0) {
    dispose finalDroplet
} else {
    drain finalDroplet
}

// ============================================================
// BB4: finalCleanup (terminal)
// Dispose ECL signal droplet. Experiment ends.
// ============================================================

dispose eclSignal

// [terminal -- no further instructions; exit node for CFG]

module parasiteRecoveryDetection
module wbcDepletionDetection
module qPCRDetection

manifest WholeBlood
manifest RBCLysisBuffer
manifest Saponin
manifest PBS_EDTA_BSA
manifest iRBC_Spiked
manifest SYBRGreen_qPCR_Kit
manifest MalariaKit_Norgen

// ============================================================
// Malaria Detection Using Inertial Microfluidics
// Warkiani, Tay, Khoo, Xiaofeng, Han, Lim
// Lab on a Chip, 2015, 15, 1101-1109
// DOI: 10.1039/c4lc01058b
//
// This BioScript encodes the full sample-to-answer pipeline:
// inertial microfluidic enrichment of ring-stage P. falciparum
// parasites from lysed whole blood, followed by qPCR detection.
//
// DEVICE: High-aspect-ratio rectangular microchannel with
//   contraction-expansion array (30/90 um, height 100 um,
//   85 subunits, 20 mm total length). Outlet ratio 1:1:1.
//   Cascaded 2-stage system (3 chips; 1 pressure compensator).
//   Flow rate: 400 uL/min (Re ~102.5). Processed in ~15 min
//   per 1 mL of 0.25x diluted lysed blood.
//
// OPERATING PRINCIPLE: In high-aspect-ratio channels the high
//   shear rate along the channel width drives WBCs (6-15 um)
//   to equilibrate into two streams near the sidewalls via
//   shear-modulated inertial lift forces. Malaria parasites
//   (1-2 um, released from iRBCs by saponin lysis) are below
//   the 4 um focusing cutoff and remain unfocused, exiting
//   from all outlets (predominantly center). WBCs are removed
//   at peripheral outlets.
//
// CELL SIZE CUTOFF: Particles >=4 um are focused and depleted
//   (WBCs, iRBCs). Particles <4 um (free parasites, 1-2 um)
//   pass through unfocused to center outlet.
//
// NOTE ON LYSIS: Saponin disrupts RBC and iRBC membranes
//   while leaving malaria parasite membranes intact, releasing
//   free parasites into suspension for downstream processing.
//   RBC lysis buffer (eBioscience) removes bulk erythrocytes;
//   saponin (0.05% w/v) releases parasites from iRBCs.
//   Sample is centrifuged 2000 rpm / 5 min and resuspended
//   in PBS before microfluidic processing.
//
// NOTE ON SPIKE LEVEL: Clinically relevant parasitemia is
//   modelled by spiking 2k-10k iRBCs per mL into whole blood
//   (~2-10 parasites/uL). This is the low-level detection
//   regime that conventional microscopy (50-100 parasites/uL)
//   cannot resolve. The device achieves ~100-fold improvement.
//
// NOTE ON MIX ABSTRACTION: `mix` steps involving the
//   microfluidic chip abstract continuous-flow hydrodynamic
//   separation events (not DMF electrode mixing). The duration
//   encodes approximate processing time at 400 uL/min.
//
// CFG STRUCTURE:
//   BB1  main              -- sample prep: blood draw, iRBC
//                             spike, lysis, PBS wash
//   BB2  wbcDepletionPass  -- wbcSignal > 0: WBC depletion
//                             >99.99% confirmed; continue
//   BB3  wbcDepletionFail  -- wbcSignal <= 0: depletion
//                             insufficient; drain, re-run
//   BB4  wbcDepletionJoin  -- join: parasite recovery QC branch
//   BB5  recoveryPass      -- recoverySignal > 0: parasites
//                             successfully enriched; continue
//                             to qPCR
//   BB6  recoveryFail      -- recoverySignal <= 0: poor yield;
//                             drain enriched fraction
//   BB7  recoveryJoin      -- join: qPCR branch begins
//   BB8  qPCRPass          -- qPCRSignal > 0: positive parasite
//                             detection (Ct < threshold);
//                             dispose final sample
//   BB9  qPCRFail          -- qPCRSignal <= 0: no detection
//                             (below limit or inhibition); drain
//   BB10 finalCleanup      -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Blood draw and iRBC spiking.
//   Whole blood is collected from a healthy donor.
//   Ring-stage P. falciparum 3D7 iRBCs (2k-10k per mL) are
//   spiked into 1 mL of whole blood to emulate low-level
//   parasitemia. Spiked cell counts (2k, 5k, 10k) used to
//   generate the calibration curve for qPCR quantification.
//   iRBCs harvested from culture; parasitemia confirmed by
//   Giemsa thin-smear and haemocytometer count.
// ------------------------------------------------------------

wholeBlood     = dispense 1 units of WholeBlood
iRBCSpike      = dispense 1 units of iRBC_Spiked

spikedBlood    = mix wholeBlood with iRBCSpike for 30s

// ------------------------------------------------------------
// STEP 2: RBC bulk lysis.
//   RBC lysis buffer (eBioscience) added per manufacturer
//   instructions to remove the bulk erythrocyte population.
//   This step does NOT lyse iRBCs; infected RBCs remain intact
//   at this stage so parasites are still encapsulated.
//   Lysis performed at room temperature.
// ------------------------------------------------------------

rbcLysisBuffer = dispense 1 units of RBCLysisBuffer
lysedBlood     = mix spikedBlood with rbcLysisBuffer for 15m

// ------------------------------------------------------------
// STEP 3: Saponin lysis to release free parasites.
//   0.05% (w/v) saponin added to lyse iRBC membranes and
//   release ring-stage parasites (1-2 um) into suspension.
//   Saponin selectively disrupts cholesterol-rich RBC/iRBC
//   membranes while leaving parasite membranes intact.
//   Result: free parasites in suspension with WBCs and debris.
// ------------------------------------------------------------

saponinSoln    = dispense 1 units of Saponin
parasiteSuspension = mix lysedBlood with saponinSoln for 10m

// ------------------------------------------------------------
// STEP 4: Centrifugation and PBS wash.
//   Centrifuge at 2000 rpm for 5 min to pellet cells/debris.
//   Supernatant removed; pellet resuspended in 1x PBS.
//   Diluted to 0.25x with PBS (4-fold dilution) to reduce
//   WBC-WBC interactions that compromise depletion efficiency.
//   0.25x dilution yields 99.90% WBC depletion in single cycle
//   vs 47% at 1x. Dilution is the key sample-prep parameter.
//   `heat` at 4c models centrifugation pelleting step (300s).
// ------------------------------------------------------------

pbsBuffer      = dispense 1 units of PBS_EDTA_BSA
heat parasiteSuspension at 4c for 300s

washedSample   = mix parasiteSuspension with pbsBuffer for 5m

// ------------------------------------------------------------
// STEP 5: Device priming.
//   Microfluidic chip primed with 1x PBS + 2 mM EDTA + 0.5%
//   BSA at 500 uL/min for 2 min to block non-specific adhesion
//   and equilibrate the PDMS channel surfaces.
//   `mix` abstracts continuous-flow channel priming.
// ------------------------------------------------------------

primingBuffer  = dispense 1 units of PBS_EDTA_BSA
primedChip     = mix washedSample with primingBuffer for 2m

// ------------------------------------------------------------
// STEP 6: Stage 1 inertial microfluidic separation.
//   Sample loaded at 400 uL/min (Re ~102.5) through the
//   30/90 um contraction-expansion array (100 um height,
//   85 subunits, 20 mm total). WBCs (6-15 um) focus to
//   channel sidewalls via shear-modulated inertial lift and
//   wall-induced lift force equilibration.
//   Free parasites (1-2 um) remain unfocused; exit all outlets.
//   Center outlet (1:1:1 ratio) collects enriched fraction.
//   Processing time: ~2.5 min per 1 mL at 400 uL/min.
//   `mix` abstracts the continuous-flow separation event.
//   A fresh PBS aliquot (chipBuffer1) is used here to avoid
//   re-using primingBuffer (already consumed in primedChip).
// ------------------------------------------------------------

chipBuffer1    = dispense 1 units of PBS_EDTA_BSA
stage1Enriched = mix primedChip with chipBuffer1 for 3m

// QC gate: WBC depletion efficiency check after Stage 1.
// wbcDepletionDetection module abstracts flow-cytometry-based
// WBC counting (CD45-APC antibody staining; Olympus IX81
// epifluorescent microscope with motorized stage).
// Expected: ~99.90% WBC depletion at Re 102.5 (single cycle).

wbcSignal1     = detect wbcDepletionDetection on stage1Enriched for 30s

// ============================================================
// BB2 / BB3: Stage 1 WBC depletion QC gate
// Pass (BB2): wbcSignal1 > 0 -> depletion confirmed;
//             carry stage1Enriched forward to Stage 2.
// Fail (BB3): wbcSignal1 <= 0 -> WBC contamination too high;
//             drain and re-run at optimal Re (adjust flow rate
//             or dilution factor off-chip).
// Both branches converge at BB4 (wbcDepletionJoin).
//
// NOTE: pass branch does NOT dispose stage1Enriched here;
// it is carried implicitly into BB4 as the Stage 2 input.
// drain in the fail branch correctly discards the fraction.
// ============================================================

if (wbcSignal1 > 0) {
    dispose stage1Enriched
} else {
    drain stage1Enriched
}

// ============================================================
// BB4: wbcDepletionJoin
// Dispose Stage 1 WBC QC signal. Control falls into Stage 2
// cascaded enrichment and parasite recovery QC branch.
// ============================================================

dispose wbcSignal1

// ------------------------------------------------------------
// STEP 7: Stage 2 cascaded inertial microfluidic separation.
//   Center outlet fraction from Stage 1 (stage1Enriched) is
//   fed directly into Stage 2 chip (cascaded configuration;
//   pressure compensator chip in parallel for flow balancing).
//   Stage 2 repeats the same 30/90 um separation at 400 uL/min,
//   achieving a second cycle of WBC depletion. Combined:
//   ~99.99% WBC depletion after 2 cycles. Collection efficiency
//   of free parasites: ~70.9 +/- 11.4% in blood.
//   Parasites collected from center outlet into 200 uL PBS.
//   chipBuffer2 is a fresh PBS aliquot for Stage 2 priming.
// ------------------------------------------------------------

chipBuffer2       = dispense 1 units of PBS_EDTA_BSA

// Stage 2 chip run: stage1Enriched (center outlet fraction)
// re-injected as actual input. No fresh dispense needed here.
stage2Enriched    = mix stage1Enriched with chipBuffer2 for 3m

// Parasite recovery QC: FACS-based collection efficiency check.
// parasiteRecoveryDetection abstracts fluorescence counting of
// 1.5 um bead surrogates (proxy for parasites) in center outlet
// vs total inlet count. Expected: ~60% collection (2-cycle).

recoverySignal    = detect parasiteRecoveryDetection on stage2Enriched for 30s

// ============================================================
// BB5 / BB6: Parasite recovery QC gate
// Pass (BB5): recoverySignal > 0 -> sufficient parasite yield
//             in enriched fraction; carry stage2Enriched
//             forward to DNA extraction.
// Fail (BB6): recoverySignal <= 0 -> unacceptable parasite
//             loss during separation; drain enriched fraction.
// Both branches converge at BB7 (recoveryJoin).
//
// NOTE: pass branch drains only the QC signal; stage2Enriched
// is carried forward to extraction step in BB7.
// ============================================================

if (recoverySignal > 0) {
    drain recoverySignal
} else {
    drain stage2Enriched
}

// ============================================================
// BB7: recoveryJoin
// Dispose parasite recovery QC signal. Control falls into
// the qPCR quantification branch (BB8/BB9).
// ============================================================

dispose recoverySignal

// ------------------------------------------------------------
// STEP 8: Parasite DNA extraction for qPCR.
//   Enriched parasites (stage2Enriched, 200 uL PBS) are
//   processed with the Norgen malaria kit (#34800, Canada)
//   per manufacturer instructions. This step extracts and
//   purifies parasite genomic DNA for PCR amplification.
//   WBC removal upstream is critical: residual WBC DNA cross-
//   reacts with p.f.-specific primers and PCR inhibitors in
//   WBC genomic material suppress amplification.
//   Without enrichment, 2k/mL parasitemia is undetectable;
//   after enrichment, detection reaches ~1 parasite/uL.
// ------------------------------------------------------------

malariaKit     = dispense 1 units of MalariaKit_Norgen
sybr           = dispense 1 units of SYBRGreen_qPCR_Kit

extractedDNA   = mix stage2Enriched with malariaKit for 20m

// ------------------------------------------------------------
// STEP 9: qPCR amplification and detection.
//   StepOnePlus (Applied Biosystems) with SYBR Green.
//   Protocol: 95 C for 3 min (initial denaturation), then
//   40 cycles of [94 C for 15 s, 60 C for 30 s].
//   Melt curve: 65 C to 95 C, reading every 0.1 C after 5 s hold.
//   Ct threshold: default fluorescence threshold settings.
//   Primer specificity confirmed by melt curve (two peaks:
//   spiked iRBCs and isoC internal control from malaria kit).
//   Calibration curve: 2k, 5k, 10k iRBC standards in blood.
//   Recovery % = DNA from enriched sample / DNA from same
//   number of unenriched parasites (both at same initial count).
//   `heat` encodes the PCR thermal cycling: 3 min at 95 C
//   (initial denature) then 40 cycles at 94/60 C abstracted
//   as a 40-cycle x 45 s = 1800 s (30 min) block at 60 C.
// ------------------------------------------------------------

qPCRMix        = mix extractedDNA with sybr for 5s

// Initial denaturation: 95 C for 3 min.
heat qPCRMix at 95c for 3m

// 40 amplification cycles (94 C / 60 C); abstracted at 60 C
// for 30 min total (40 cycles x ~45 s per cycle).
heat qPCRMix at 60c for 30m

// Melt curve analysis: 65 C to 95 C ramp (abstracted at 80 C
// for 5 min to represent the ramp period with 0.1 C steps).
heat qPCRMix at 80c for 5m

// qPCRDetection module abstracts StepOnePlus Ct readout,
// melt curve peak analysis, and calibration curve lookup.
// Signal > 0: Ct below threshold -> positive parasite detection.
// Expected detection range: 10^3 to 10^4 P. falciparum per mL
// (~2-10 parasites/uL). ~100-fold more sensitive than microscopy.

qPCRSignal     = detect qPCRDetection on qPCRMix for 10s

// ============================================================
// BB8 / BB9: qPCR detection QC gate
// Pass (BB8): qPCRSignal > 0 -> parasite DNA detected above
//             Ct threshold; sample is malaria-positive.
//             Dispose final PCR product.
// Fail (BB9): qPCRSignal <= 0 -> no amplification above
//             threshold; either below detection limit or
//             residual PCR inhibition; drain qPCR product.
// Both branches converge at BB10 (finalCleanup).
// ============================================================

if (qPCRSignal > 0) {
    dispose qPCRMix
} else {
    drain qPCRMix
}

// ============================================================
// BB10: finalCleanup (terminal)
// Dispose qPCR detection signal. Experiment ends.
// ============================================================

dispose qPCRSignal

// [terminal -- no further instructions; exit node for CFG]

