module viabilityDetection
module transformationQC

manifest E_coli
manifest S_cerevisiae
manifest C_cryptica
manifest LB_Broth
manifest YPD_Broth
manifest F2_Media
manifest EthidiumHomodimer1
manifest TritonX100
manifest pTriEx_YFP_Plasmid
manifest CaCl2_Solution

instructions:

// ============================================================
// Integrated Microbioreactor for Culture and Analysis of
// Bacteria, Algae and Yeast ("BAY" microbioreactor).
// Au, Shih, Wheeler - Biomed Microdevices (2011) 13:41-50
// DOI: 10.1007/s10544-010-9469-3
//
// Protocol: automated digital-microfluidic (DMF) culture of
// three microorganism types (E. coli, S. cerevisiae,
// C. cryptica) in a ~70 uL "mother drop", with periodic
// semi-continuous circular-path mixing, absorbance-based
// density monitoring, an on-chip fluorescent viability assay
// (EthD-1 +/- Triton X-100) for yeast, and on-chip genetic
// transformation of E. coli with a YFP reporter plasmid.
//
// NOTE ON DAUGHTER-DROPLET ABSTRACTION: The paper dispenses
// ~7 uL daughter droplets from the ~70 uL mother drop for
// absorbance measurement, then returns them to the mother
// drop afterward (Section 2.5, Fig. 2b). lilott8/BioScript
// does not reliably support split/re-merge of a single mother
// droplet without stranding fragments (see array/split
// limitations noted in reference protocols). Absorbance
// detection is therefore modelled directly on the culture
// droplet itself (non-consumptive `detect`), which is
// functionally equivalent to the daughter-droplet round trip
// for CFG purposes.
//
// NOTE ON MIXING/INCUBATION ABSTRACTION: Semi-continuous
// circular-path mixing (Fig. 2a, ~1.5 s actuation per cycle,
// repeated at Table 1 intervals) is modelled as a single
// short `mix` step (inoculation) followed by a `heat` step
// at the culture temperature for the duration of one
// absorbance-measurement interval (Table 1: bacteria 1 h,
// yeast 2 h, algae 24 h), representing one representative
// growth/measurement cycle rather than the full multi-day
// unrolled loop (BioScript has no loop construct).
//
// CFG STRUCTURE:
//   BB1  main            -- entry: bacteria culture + density check
//   BB2  bactPass         -- bactGrowthSignal > 0: culture continues
//   BB3  bactFail         -- bactGrowthSignal <= 0: contamination, drain
//   BB4  bactJoin         -- join: yeast culture arm begins
//   BB5  yeastPass        -- yeastGrowthSignal > 0: culture continues
//   BB6  yeastFail        -- yeastGrowthSignal <= 0: contamination, drain
//   BB7  yeastJoin        -- join: algae culture arm begins
//   BB8  algaePass        -- algaeGrowthSignal > 0: culture continues
//   BB9  algaeFail        -- algaeGrowthSignal <= 0: contamination, drain
//   BB10 algaeJoin        -- join: yeast viability assay begins
//   BB11 viabilityPass    -- viabilitySignal > 0: viable cells, dispose
//   BB12 viabilityFail    -- viabilitySignal <= 0: non-viable, drain
//   BB13 viabilityJoin    -- join: E. coli transformation begins
//   BB14 transformPass    -- transformSignal > 0: colonies formed, dispose
//   BB15 transformFail    -- transformSignal <= 0: no colonies, drain
//   BB16 finalCleanup     -- terminal: dispose transformation QC signal
// ============================================================

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// BACTERIA ARM (Section 2.2/2.5, Table 1): E. coli DH5alpha
//   grown in LB broth at 37 C. Mother drop mixed in a circular
//   pattern every 2.5 min; absorbance (600 nm) measured every
//   1 h and used as the growth/contamination QC signal.
// ------------------------------------------------------------

motherDropBact  = dispense 1 units of E_coli
lbMedia         = dispense 1 units of LB_Broth
bactCulture     = mix motherDropBact with lbMedia for 5s

// Represents one 1-h inter-measurement incubation interval
// (Table 1: absorbance measurement frequency, bacteria = 1 h)
// under semi-continuous circular mixing at 37 C.
heat bactCulture at 37c for 60m

bactGrowthSignal = detect densityDetection on bactCulture for 1s

// ============================================================
// BB2 / BB3: Bacteria growth QC gate
// Pass (BB2): bactGrowthSignal > 0 -> absorbance increasing,
//             culture proceeding normally; dispose (continue
//             represented by disposal of this cycle's droplet).
// Fail (BB3): bactGrowthSignal <= 0 -> no growth/contamination;
//             drain.
// Both branches converge at BB4 (bactJoin).
// ============================================================

if (bactGrowthSignal > 0) {
    dispose bactCulture
} else {
    drain bactCulture
}

// ============================================================
// BB4: bactJoin
// Dispose bacteria growth QC signal. Control falls into the
// yeast culture arm (BB5/BB6).
// ============================================================

dispose bactGrowthSignal

// ------------------------------------------------------------
// YEAST ARM (Section 2.2/2.5, Table 1): S. cerevisiae BY4741
//   grown in YPD broth at 30 C. Mother drop mixed every
//   2.5 min; absorbance (600 nm) measured every 2 h.
// ------------------------------------------------------------

motherDropYeast   = dispense 1 units of S_cerevisiae
ypdMedia          = dispense 1 units of YPD_Broth
yeastCulture      = mix motherDropYeast with ypdMedia for 5s

// Represents one 2-h inter-measurement incubation interval
// (Table 1: absorbance measurement frequency, yeast = 2 h).
heat yeastCulture at 30c for 120m

yeastGrowthSignal = detect densityDetection on yeastCulture for 1s

// ============================================================
// BB5 / BB6: Yeast growth QC gate
// Pass (BB5): yeastGrowthSignal > 0 -> culture proceeding
//             normally; dispose.
// Fail (BB6): yeastGrowthSignal <= 0 -> no growth/contamination;
//             drain.
// Both branches converge at BB7 (yeastJoin).
// ============================================================

if (yeastGrowthSignal > 0) {
    dispose yeastCulture
} else {
    drain yeastCulture
}

// ============================================================
// BB7: yeastJoin
// Dispose yeast growth QC signal. Control falls into the
// algae culture arm (BB8/BB9).
// ============================================================

dispose yeastGrowthSignal

// ------------------------------------------------------------
// ALGAE ARM (Section 2.2/2.5, Table 1): C. cryptica grown in
//   f/2 medium (+ biotin/cyanocobalamin) at 14 C under
//   continuous illumination. Mother drop mixed every 120 min;
//   absorbance (660 nm) measured every 24 h.
// ------------------------------------------------------------

motherDropAlgae   = dispense 1 units of C_cryptica
f2Media           = dispense 1 units of F2_Media
algaeCulture      = mix motherDropAlgae with f2Media for 5s

// Represents one 24-h inter-measurement incubation interval
// (Table 1: absorbance measurement frequency, algae = 24 h).
heat algaeCulture at 14c for 1440m

algaeGrowthSignal = detect densityDetection on algaeCulture for 1s

// ============================================================
// BB8 / BB9: Algae growth QC gate
// Pass (BB8): algaeGrowthSignal > 0 -> culture proceeding
//             normally; dispose.
// Fail (BB9): algaeGrowthSignal <= 0 -> no growth/contamination;
//             drain.
// Both branches converge at BB10 (algaeJoin).
// ============================================================

if (algaeGrowthSignal > 0) {
    dispose algaeCulture
} else {
    drain algaeCulture
}

// ============================================================
// BB10: algaeJoin
// Dispose algae growth QC signal. Control falls into the
// yeast viability assay branch (BB11/BB12).
// ============================================================

dispose algaeGrowthSignal

// ------------------------------------------------------------
// VIABILITY ASSAY (Section 2.7): S. cerevisiae grown 4 h at
//   30 C with automated mixing, then merged with a dispensed
//   droplet containing 2 uM Ethidium homodimer-1 (EthD-1) and,
//   for the lytic-control condition, 0.05% (v/v) Triton X-100.
//   Combined droplet mixed along the linear path (~10
//   actuations), incubated 30 C for 1 h, and read out by
//   fluorescence (EthD-1 stains dead/compromised cells).
// ------------------------------------------------------------

yeastForAssay   = dispense 1 units of S_cerevisiae
ypdMedia2       = dispense 1 units of YPD_Broth
assayCulture    = mix yeastForAssay with ypdMedia2 for 5s

// 4-h pre-assay incubation at 30 C with automated mixing.
heat assayCulture at 30c for 240m

ethd1Dye        = dispense 1 units of EthidiumHomodimer1
tritonReagent   = dispense 1 units of TritonX100
dyeTritonMix    = mix ethd1Dye with tritonReagent for 5s

// Merge and mix along the linear path (~10 actuations).
stainedYeast    = mix assayCulture with dyeTritonMix for 10s

// Incubation at 30 C for 1 h prior to fluorescence readout.
heat stainedYeast at 30c for 60m

viabilitySignal = detect viabilityDetection on stainedYeast for 30s

// ============================================================
// BB11 / BB12: Viability QC gate
// Pass (BB11): viabilitySignal > 0 -> viable cell population
//              detected; dispose.
// Fail (BB12): viabilitySignal <= 0 -> non-viable/compromised
//              population (e.g. Triton X-100 lytic condition,
//              >99% non-viable per Fig. 5); drain.
// Both branches converge at BB13 (viabilityJoin).
// ============================================================

if (viabilitySignal > 0) {
    dispose stainedYeast
} else {
    drain stainedYeast
}

// ============================================================
// BB13: viabilityJoin
// Dispose viability QC signal. Control falls into the E. coli
// transformation branch (BB14/BB15).
// ============================================================

dispose viabilitySignal

// ------------------------------------------------------------
// TRANSFORMATION (Section 2.8): E. coli (without ampicillin
//   resistance) grown 1 h at 37 C to early/mid-log phase, then
//   chilled on ice 5 min. A droplet of pTriEx-YFP plasmid DNA
//   (200 ng) in 0.20 M CaCl2 is merged with the culture droplet
//   and mixed (~10 actuations). The combined droplet is chilled
//   on ice 1 h, heat-shocked at 42 C for 50 s, cooled on ice for
//   1 min, then incubated at 37 C for 1 h with automated mixing
//   before being spread on an ampicillin LB agar plate
//   (off-chip) to confirm successful transformation (Fig. 5d).
// ------------------------------------------------------------

competentEcoli  = dispense 1 units of E_coli
lbMedia3        = dispense 1 units of LB_Broth
transformCulture = mix competentEcoli with lbMedia3 for 5s

// 1-h growth to early/mid-log phase at 37 C with mixing.
heat transformCulture at 37c for 60m

// Pre-chill on ice for 5 min prior to plasmid addition.
heat transformCulture at 4c for 300s

plasmidDrop      = dispense 1 units of pTriEx_YFP_Plasmid
cacl2Drop        = dispense 1 units of CaCl2_Solution
plasmidCacl2Mix  = mix plasmidDrop with cacl2Drop for 5s

// Merge culture with plasmid/CaCl2 droplet, mixed along the
// sample region path (~10 actuations).
transformMix     = mix transformCulture with plasmidCacl2Mix for 10s

// Chill on ice for 1 h.
heat transformMix at 4c for 60m

// Heat shock: 42 C for 50 s.
heat transformMix at 42c for 50s

// Cool on ice for an additional 1 min.
heat transformMix at 4c for 60s

// Recovery incubation: 37 C for 1 h with automated mixing.
heat transformMix at 37c for 60m

// Off-chip readout: droplet spread on ampicillin LB agar plate
// and incubated overnight at 37 C; transformationQC abstracts
// the resulting colony-formation observation (Fig. 5d).
transformSignal  = detect transformationQC on transformMix for 30s

// ============================================================
// BB14 / BB15: Transformation QC gate
// Pass (BB14): transformSignal > 0 -> ampicillin-resistant,
//              YFP-expressing colonies observed; dispose.
// Fail (BB15): transformSignal <= 0 -> no colonies (failed
//              transformation); drain.
// Both branches converge at BB16 (finalCleanup).
// ============================================================

if (transformSignal > 0) {
    dispose transformMix
} else {
    drain transformMix
}

// ============================================================
// BB16: finalCleanup (terminal)
// Dispose transformation QC signal droplet; experiment ends.
// ============================================================

dispose transformSignal

// [terminal -- no further instructions; exit node for CFG]

module nfkbLocalizationDetection
module tnfSecretionDetection

manifest RAW2647_Macrophages
manifest PluronicF127
manifest PBS
manifest CultureMedium
manifest LPS_500ngmL
manifest TNF_CaptureBeads
manifest TNF_DetectionAntibody
manifest SecondaryFluorescentAntibody
manifest PBSTween

instructions:

// ============================================================
// High-Content Quantification of Single-Cell Immune Dynamics
// Junkin, Kaestli, Cheng, Jordi, Albayrak, Hoffmann, Tay
// Cell Reports 15, 411-422, April 2016
// DOI: 10.1016/j.celrep.2016.03.033
//
// Platform: two-layer PDMS microfluidic chip (Melin & Quake
// design). 40 individually addressable 1.35 nL isolated cell
// chambers. Membrane valves and on-chip peristaltic pumps
// control all fluid routing. Mounted on automated inverted
// epifluorescence microscope (Nikon Eclipse Ti) inside
// atmospheric enclosure (37 C, 5% CO2, saturating humidity).
//
// Cells: RAW 264.7 mouse macrophages. Non-adherent; retained
// by weir-type trap (slits without bypass) inside chambers
// functionalized to be non-adherent (Pluronic F-127 coated).
//
// Stimulation: LPS (Sigma L4524) 500 ng/mL, single 2 hr
// pulse (Fig 4B left; mimics brief pathogen exposure).
// Input switching time < 5 s via 16-inlet binary multiplexer.
//
// Readout 1 -- TNF secretion bead immunoassay (dynamic):
//   Antibody-functionalized beads (Spherotech SVP-100-4,
//   10.3 um streptavidin, biotinylated capture Ab) pre-loaded
//   in 7 bead storage chambers per column. Every 2 hr, the
//   peristaltic pump transfers medium from cell chamber to
//   binding chamber; beads circularly mixed for 90 min.
//   After binding, beads rinsed with PBS-Tween and returned
//   to storage. At run end, detection Ab + secondary Ab
//   complete the sandwich; beads imaged; intensity correlated
//   to on-chip calibration curve (R2 = 0.9984, Fig 2B).
//   LOD: ~60,000 TNF molecules. 7 time windows: 0-2, 2-4,
//   4-6, 6-8, 8-10, 10-12, 12-14 hr post-stimulus.
//
// Readout 2 -- NF-kB (RelA) localization (dynamic):
//   Time-lapse epifluorescence imaging every ~6 min.
//   Cells express RelA-GFP; nuclear/cytoplasmic ratio
//   reports NF-kB activation state continuously.
//
// BioScript abstraction notes:
//   - `mix` is a consuming operation on both operands.
//     The "cell thread" is modelled as a fluid variable
//     that is re-produced at every feeding or sampling step
//     by mixing with the incoming fresh medium or bead-wash
//     product. This reflects how peristaltic pumping cycles
//     fluid through and out of the cell chamber.
//   - `mix cellVar with LPS_500ngmL` abstracts multiplexer
//     routing of the LPS inlet into the chamber for 2 hr.
//   - `heat` at 37c models on-chip incubation (non-consuming).
//   - Bead time-points: each window uses a freshly dispensed
//     bead variable; the washed bead product carries into the
//     next step as the cell-thread carrier, maintaining a
//     single linear ownership chain through the experiment.
//   - `detect nfkbLocalizationDetection` abstracts nuclear
//     RelA ratio measurement; consumes the cell variable.
//   - `detect tnfSecretionDetection` abstracts bead
//     fluorescence + calibration curve lookup (baseline
//     bead used as QC gate key; returns > 0 if any bead
//     window exceeds LOD of ~60,000 TNF molecules).
//   - h token unsupported: 2 hr = 120m throughout.
//   - `dispose` in pass-branches; `drain` in fail-branches.
//
// CFG STRUCTURE:
//   BB1  main           -- chip prep, cell loading, baseline
//                          TNF assay (t0), LPS 2 hr pulse,
//                          6x post-stimulus TNF assays,
//                          sandwich Ab completion, NF-kB detect
//   BB2  nfkbPass       -- nfkbSignal > 0: RelA nuclear peak
//                          detected; dispose cell variable
//   BB3  nfkbFail       -- nfkbSignal <= 0: no activation;
//                          drain cell variable
//   BB4  nfkbJoin       -- join: TNF QC gate follows
//   BB5  tnfPass        -- tnfSignal > 0: TNF detected;
//                          dispose baseline bead variable
//   BB6  tnfFail        -- tnfSignal <= 0: all beads below
//                          LOD; drain baseline bead variable
//   BB7  finalCleanup   -- terminal: dispose QC signals
// ============================================================

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Chip surface preparation.
//   All internal surfaces except cell chambers coated with
//   2 mg/mL Pluronic F-127 in DI water overnight via control
//   script to block protein adsorption and bead adhesion.
//   Rinsed extensively with PBS before cell loading.
//   `mix` abstracts the automated overnight rinse sequence.
// ------------------------------------------------------------

pluronicSol  = dispense 1 units of PluronicF127
pbsRinse     = dispense 1 units of PBS
devicePrimed = mix pluronicSol with pbsRinse for 720m

// ------------------------------------------------------------
// STEP 2: Cell loading.
//   RAW 264.7 macrophages (versene-detached, 20 um filtered,
//   1e5-3.5e5 cells/mL) flowed through inlets. Binary
//   multiplexer directs cells to individual chambers. Weir
//   trap captures non-adherent macrophages. < 10 min total.
//   `mix` abstracts the flow-through trapping event.
// ------------------------------------------------------------

macrophages  = dispense 1 units of RAW2647_Macrophages
cellsLoaded  = mix macrophages with devicePrimed for 10m

// ------------------------------------------------------------
// STEP 3: Post-loading equilibration.
//   Fresh medium pumped into chamber; cells equilibrate
//   inside sealed chambers at 37 C / 5% CO2 for 2 hr.
// ------------------------------------------------------------

medEq        = dispense 1 units of CultureMedium
cellsEq      = mix cellsLoaded with medEq for 10m
heat cellsEq at 37c for 120m

// ------------------------------------------------------------
// STEP 4: Baseline TNF bead capture (t = 0-2 hr, pre-LPS).
//   Medium surrounding cells sampled for 2 hr to establish
//   pre-stimulus TNF baseline. Bead_1 transferred from
//   storage to binding chamber; medium + bead mixed by
//   circular peristaltic pumping for 90 min (Fig 2A).
//   Bead rinsed with PBS-Tween; returned to storage.
//   `mix cellsEq with medT0` models the medium sampling
//   step (consumes cellsEq); bead1Washed carries the
//   cell-thread forward into the stimulation phase.
// ------------------------------------------------------------

medT0        = dispense 1 units of CultureMedium
sampleT0     = mix cellsEq with medT0 for 120m

bead1        = dispense 1 units of TNF_CaptureBeads
pbt1         = dispense 1 units of PBSTween
bead1Bound   = mix sampleT0 with bead1 for 90m
bead1Washed  = mix bead1Bound with pbt1 for 5m

// ------------------------------------------------------------
// STEP 5: LPS stimulation -- 2 hr pulse.
//   LPS at 500 ng/mL injected via multiplexer into cell
//   chamber for exactly 2 hr. Switching time < 5 s.
//   `mix bead1Washed with lpsInput` abstracts the LPS
//   inlet routing; bead1Washed carries the cell state
//   as fluid thread; result is cellsStim.
// ------------------------------------------------------------

lpsInput     = dispense 1 units of LPS_500ngmL
cellsStim    = mix bead1Washed with lpsInput for 120m
heat cellsStim at 37c for 120m

// ------------------------------------------------------------
// STEP 6: LPS washout.
//   Multiplexer switches back to medium inlet; LPS-free
//   medium flows through chamber (< 5 s switchover time).
// ------------------------------------------------------------

medWash      = dispense 1 units of CultureMedium
cellsWashed  = mix cellsStim with medWash for 10m

// ------------------------------------------------------------
// STEP 7: TNF bead capture -- time point 1 (0-2 hr post-LPS).
//   Medium sampled from chamber; bead_2 moved to binding
//   chamber and mixed for 90 min; rinsed with PBS-Tween.
//   bead2Washed carries cell thread into next window.
// ------------------------------------------------------------

medTP1       = dispense 1 units of CultureMedium
sampleTP1    = mix cellsWashed with medTP1 for 120m

bead2        = dispense 1 units of TNF_CaptureBeads
pbt2         = dispense 1 units of PBSTween
bead2Bound   = mix sampleTP1 with bead2 for 90m
bead2Washed  = mix bead2Bound with pbt2 for 5m

heat bead2Washed at 37c for 120m

// ------------------------------------------------------------
// STEP 8: TNF bead capture -- time point 2 (2-4 hr post-LPS).
// ------------------------------------------------------------

medTP2       = dispense 1 units of CultureMedium
sampleTP2    = mix bead2Washed with medTP2 for 120m

bead3        = dispense 1 units of TNF_CaptureBeads
pbt3         = dispense 1 units of PBSTween
bead3Bound   = mix sampleTP2 with bead3 for 90m
bead3Washed  = mix bead3Bound with pbt3 for 5m

heat bead3Washed at 37c for 120m

// ------------------------------------------------------------
// STEP 9: TNF bead capture -- time point 3 (4-6 hr post-LPS).
// ------------------------------------------------------------

medTP3       = dispense 1 units of CultureMedium
sampleTP3    = mix bead3Washed with medTP3 for 120m

bead4        = dispense 1 units of TNF_CaptureBeads
pbt4         = dispense 1 units of PBSTween
bead4Bound   = mix sampleTP3 with bead4 for 90m
bead4Washed  = mix bead4Bound with pbt4 for 5m

heat bead4Washed at 37c for 120m

// ------------------------------------------------------------
// STEP 10: TNF bead capture -- time point 4 (6-8 hr post-LPS).
// ------------------------------------------------------------

medTP4       = dispense 1 units of CultureMedium
sampleTP4    = mix bead4Washed with medTP4 for 120m

bead5        = dispense 1 units of TNF_CaptureBeads
pbt5         = dispense 1 units of PBSTween
bead5Bound   = mix sampleTP4 with bead5 for 90m
bead5Washed  = mix bead5Bound with pbt5 for 5m

heat bead5Washed at 37c for 120m

// ------------------------------------------------------------
// STEP 11: TNF bead capture -- time point 5 (8-10 hr post-LPS).
// ------------------------------------------------------------

medTP5       = dispense 1 units of CultureMedium
sampleTP5    = mix bead5Washed with medTP5 for 120m

bead6        = dispense 1 units of TNF_CaptureBeads
pbt6         = dispense 1 units of PBSTween
bead6Bound   = mix sampleTP5 with bead6 for 90m
bead6Washed  = mix bead6Bound with pbt6 for 5m

heat bead6Washed at 37c for 120m

// ------------------------------------------------------------
// STEP 12: TNF bead capture -- time point 6 (10-12 hr post-LPS).
//   Final medium sampling window. bead7Washed carries the
//   cell-thread terminal state into the sandwich completion.
// ------------------------------------------------------------

medTP6       = dispense 1 units of CultureMedium
sampleTP6    = mix bead6Washed with medTP6 for 120m

bead7        = dispense 1 units of TNF_CaptureBeads
pbt7         = dispense 1 units of PBSTween
bead7Bound   = mix sampleTP6 with bead7 for 90m
bead7Washed  = mix bead7Bound with pbt7 for 5m

// ------------------------------------------------------------
// STEP 13: Sandwich assay completion -- detection antibodies.
//   After all 7 time-point bead captures, detection Ab
//   (genwaybio GWB-489500, 3.19 ug/mL) applied for 30 min
//   with circular mixing, then secondary fluorescent Ab
//   (USB I1903-12H, 3.3 ug/mL) for 30 min. PBS-Tween rinse
//   between steps. bead7Washed carries the accumulated
//   cell-state thread; `mix` with detAb and secAb models
//   the Ab incubation over all stored beads simultaneously.
// ------------------------------------------------------------

detAb        = dispense 1 units of TNF_DetectionAntibody
secAb        = dispense 1 units of SecondaryFluorescentAntibody

detStep      = mix bead7Washed with detAb for 30m
sandwichDone = mix detStep with secAb for 30m

// ------------------------------------------------------------
// STEP 14: NF-kB (RelA) localization -- aggregate QC readout.
//   Automated stage images every ~6 min throughout the 20 hr
//   run in GFP and brightfield channels. RelA-GFP nuclear/
//   cytoplasmic ratio computed per frame by MATLAB. Here,
//   nfkbLocalizationDetection abstracts the binary
//   determination: was a RelA nuclear peak observed (> 2 SD
//   above pre-stimulus baseline) during or after LPS pulse?
//   ~93.6% of cells (n=46) show NF-kB activation peak
//   following LPS stimulation (Fig 6A).
//   `detect` is applied to sandwichDone which holds the
//   terminal cell state; this consumes sandwichDone.
// ------------------------------------------------------------

nfkbSignal   = detect nfkbLocalizationDetection on sandwichDone for 30s

// ============================================================
// BB2 / BB3: NF-kB activation QC gate
// Pass (BB2): nfkbSignal > 0 -> RelA nuclear peak detected;
//             cell categorised NF-kB+; dispose sandwichDone.
// Fail (BB3): nfkbSignal <= 0 -> no activation peak;
//             cell categorised NF-kB-; drain sandwichDone.
// Both branches converge at BB4 (nfkbJoin).
// ============================================================

if (nfkbSignal > 0) {
    dispose sandwichDone
} else {
    drain sandwichDone
}

// ============================================================
// BB4: nfkbJoin
// Dispose NF-kB QC signal. Control falls into TNF
// secretion QC gate (BB5/BB6).
// ============================================================

dispose nfkbSignal

// ------------------------------------------------------------
// STEP 15: TNF secretion fluorescence readout.
//   Beads in storage chambers imaged (brightfield + GFP
//   channel). Fluorescence correlated to on-chip calibration
//   curve (R2 = 0.9984, LOD ~60,000 molecules, Fig 2B).
//   tnfSecretionDetection applied to bead1Washed (baseline
//   bead, still alive from STEP 4) as the QC gate key;
//   signal > 0 if any time-point bead exceeds LOD.
//   ~93.5% of cells produce detectable TNF (Fig 6A).
// ------------------------------------------------------------

tnfSignal    = detect tnfSecretionDetection on bead1Washed for 30s

// ============================================================
// BB5 / BB6: TNF secretion QC gate
// Pass (BB5): tnfSignal > 0 -> measurable TNF secretion in
//             at least one 2 hr window (TNF+ cell);
//             dispose bead1Washed.
// Fail (BB6): tnfSignal <= 0 -> all time-point beads below
//             LOD (TNF- cell, ~6.5% per Fig 6A); drain.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (tnfSignal > 0) {
    dispose bead1Washed
} else {
    drain bead1Washed
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose TNF QC signal. Experiment ends.
// ============================================================

dispose tnfSignal

// [terminal -- no further instructions; exit node for CFG]

module bacterialRecoveryQC
module rRNASpeciesDetection
module mRNASusceptibilityDetection

manifest WholeBlood
manifest PBS_BSA_Buffer
manifest SheathFluid
manifest EcoliClinicalIsolate
manifest EcoliClinicalIsolate_Susceptible
manifest EcoliClinicalIsolate_Resistant
manifest RLT_Lysis_Buffer
manifest Ciprofloxacin_Stock

// ============================================================
// Direct Detection and Drug-Resistance Profiling of
// Bacteremias Using Inertial Microfluidics
// Hou, Bhattacharyya, Hung, Han - Lab Chip 2015, 15, 2297
// DOI: 10.1039/c5lc00311c
//
// PROTOCOL OVERVIEW:
//   Two sequential diagnostic workflows are encoded:
//
//   WORKFLOW 1 (Species Identification via rRNA):
//     Bacteria (~100 cfu/mL) are isolated from 3x-diluted
//     whole blood using a PDMS spiral microchannel device
//     (500 um x 80 um, ~10 cm length) operating on Dean
//     Flow Fractionation (DFF). Blood is pumped at 1700 uL/min
//     via syringe pump; sheath fluid (PBS+BSA) at ~10x ratio
//     pins sample at the outer wall. Larger blood cells
//     (RBCs ~6-8 um; leukocytes ~7-12 um) focus inertially
//     at the inner wall and exit the waste outlet. Bacteria
//     (<1 um) and platelets (~2-3 um) follow Dean vortices,
//     complete a full Dean cycle, and exit at the bacterial
//     outlet. Bacterial recovery >65% across 10^2-10^4 cfu/mL.
//     Bacterial eluate is pelleted (16,000 x g), resuspended
//     in 50 uL PBS, lysed with 4x RLT buffer + BME, and
//     analysed by NanoString rRNA hybridization (16S/23S
//     species-specific probes) for pathogen ID without
//     culture or enzymatic amplification. Total time: ~8 h.
//
//   WORKFLOW 2 (Antibiotic Susceptibility via mRNA):
//     Clinical E. coli isolates at ~10^5 cfu/mL (either
//     spiked directly or grown 7.5 h in BACTEC blood culture
//     bottles from 1 cfu/mL) are processed through the same
//     DFF spiral device. Recovered bacteria are exposed to
//     ciprofloxacin (2.5 mcg/mL, 37 C, 30 min), then lysed
//     and analysed by NanoString mRNA detection. A set of 6
//     ciprofloxacin-responsive E. coli transcripts and 3
//     control (non-responsive) transcripts are quantified.
//     The Transcriptional Susceptibility Score (analogous to
//     Squared Pyramidal Distance) discriminates susceptible
//     (score ~0) from resistant (score ~1) strains.
//     Total time: <8 h including separation and RNA detection.
//
// KEY PHYSICAL PARAMETERS:
//   Channel: 500 um (w) x 80 um (h), spiral, ~10 cm length
//   Flow rate: 1700 uL/min total (sample:sheath = 1:10)
//   Sample: 3x diluted whole blood (~15% hematocrit)
//   Throughput: ~20 min per mL of whole blood per chip
//   Bacterial recovery: >65% (vs ~30% by low-speed centrifuge)
//   rRNA detection sensitivity: ~100 cfu/mL (3 mL input)
//   mRNA detection sensitivity: ~10^5 cfu/mL
//
// TEMPERATURE CONTROL:
//   Lysis: room temperature (25 C) for 5 min
//   Ciprofloxacin exposure: 37 C for 30 min
//   NanoString hybridization: 2 h (shortened from standard)
//   `heat` statements model these incubation steps.
//
// NOTE ON SEPARATION ABSTRACTION:
//   The `mix` steps used for DFF separation abstract a
//   continuous-flow spiral microchannel operation, not a DMF
//   electrode mixing event. At each `mix`, the sample stream
//   traverses the spiral under inertial and Dean drag forces.
//   Blood cells exit at the waste outlet (inner wall focus)
//   while bacteria exit at the bacterial outlet (Dean cycle
//   recirculation to outer wall). This is a flow-through
//   fractionation event modelled within BioScript's `mix`
//   abstraction for label-free cell separation.
//
// NOTE ON BIOSCRIPT COMPILER (lilott8/BioScript):
//   - Duration tokens: s and m only (no h). All incubations
//     stated in hours in the paper are converted to minutes.
//   - No array indexing; all droplets are scalar variables.
//   - `split` avoided to prevent stranded droplet compiler
//     errors; dilutions use explicit multi-dispense + mix.
//   - `drain` used for QC fail paths; `dispose` for pass paths.
//
// CFG STRUCTURE:
//   BB1  main                -- entry: sample prep and DFF separation
//   BB2  recoveryPass        -- recoverySignal > 0: adequate bacterial
//                               yield; carry forward to lysis
//   BB3  recoveryFail        -- recoverySignal <= 0: insufficient yield;
//                               drain and abort
//   BB4  recoveryJoin        -- join: rRNA species ID branch begins
//   BB5  rRNAPass            -- rRNASignal > 0: pathogen identified;
//                               dispose and proceed to susceptibility
//   BB6  rRNAFail            -- rRNASignal <= 0: unidentifiable pattern;
//                               drain
//   BB7  rRNAJoin            -- join: mRNA susceptibility branch begins
//   BB8  susceptibilityPass  -- susceptibilitySignal <= 0 (score near 0):
//                               susceptible organism confirmed; dispose
//   BB9  susceptibilityFail  -- susceptibilitySignal > 0 (score near 1):
//                               resistant organism flagged; drain
//   BB10 finalCleanup        -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prepare 3x-diluted whole blood sample.
//   Fresh human whole blood with EDTA anticoagulant is diluted
//   1:3 (v/v) with PBS + 0.1% BSA (sample buffer). BSA prevents
//   non-specific adsorption to tubing and microchannel walls.
//   Hematocrit target: ~15% (optimal for spiral device).
//   For rRNA experiments: bacteria spiked at ~100 cfu/mL.
//   For mRNA experiments: bacteria spiked at ~10^5 cfu/mL.
//
//   NOTE: Both susceptible and resistant E. coli clinical
//   isolates are processed identically up to ciprofloxacin
//   exposure. A single representative E. coli isolate is
//   encoded here. The susceptible/resistant classification
//   is resolved downstream by the Transcriptional
//   Susceptibility Score in WORKFLOW 2.
// ------------------------------------------------------------

wholeBlood       = dispense 1 units of WholeBlood
sampleBuffer     = dispense 1 units of PBS_BSA_Buffer
bacterialSample  = dispense 1 units of EcoliClinicalIsolate

// 1:3 dilution: mix blood with 3 volumes sample buffer.
// Three buffer units chained to accumulate correct dilution.
buf1             = dispense 1 units of PBS_BSA_Buffer
buf2             = dispense 1 units of PBS_BSA_Buffer

bufferAcc        = mix buf1 with buf2 for 5s
dilutedBlood     = mix wholeBlood with bufferAcc for 5s

// Spike bacteria into diluted blood immediately before loading.
spikedBloodSample = mix dilutedBlood with bacterialSample for 5s

// ------------------------------------------------------------
// STEP 2: Prime the spiral microchannel device.
//   Load 1x PBS + 0.1% BSA as sheath fluid via inner inlet
//   (425 um width) at ~10x the sample flow rate to pin the
//   sample stream near the outer wall at the inlet.
//   Device is pre-wetted to remove air bubbles and
//   condition channel walls to minimise non-specific adhesion.
// ------------------------------------------------------------

sheathPrime = dispense 1 units of SheathFluid
devicePrime = mix sheathPrime with spikedBloodSample for 2s

// ------------------------------------------------------------
// STEP 3: DFF separation - inertial focusing of blood cells
//   and Dean migration of bacteria.
//   Spiral device operated at 1700 uL/min total flow.
//   Sample loaded at outer inlet (75 um width); sheath at
//   inner inlet (425 um width). Sample:sheath = 1:10.
//   Over ~10 cm spiral length, RBCs and leukocytes experience
//   dominant inertial lift (F_L) and focus at inner wall.
//   Bacteria (<1 um, ap/h << 0.07) are unaffected by F_L and
//   follow Dean drag (F_D), completing a full Dean Cycle (DC1)
//   to recirculate to the outer wall and exit the bacterial
//   outlet (200 um width).
//   Process time: ~20 min per mL whole blood.
//
//   `mix` abstracts this continuous-flow separation event.
//   Output `bacterialEluate` represents the fluid collected
//   from the bacterial outlet; `bloodWaste` represents the
//   inner-wall (waste) outlet stream.
// ------------------------------------------------------------

sheathFlow     = dispense 1 units of SheathFluid
bacterialEluate = mix devicePrime with sheathFlow for 20m

// ------------------------------------------------------------
// STEP 4: Concentrate bacterial eluate.
//   Eluate collected from bacterial outlet is pelleted by
//   centrifugation at 16,000 x g. Supernatant removed.
//   Pellet resuspended in 50 uL 1x PBS for downstream steps.
//   `heat` at 25 C (room temperature) abstracts centrifugation
//   and resuspension as a defined physical processing step.
// ------------------------------------------------------------

heat bacterialEluate at 25c for 5m

// ------------------------------------------------------------
// STEP 5: QC - verify adequate bacterial recovery.
//   In the paper, recovery is verified by cfu counting on
//   LB agar plates (>65% recovery expected across tested
//   concentrations). This QC gate ensures sufficient bacterial
//   material for downstream RNA detection before proceeding.
//   bacterialRecoveryQC module abstracts the cfu enumeration.
// ------------------------------------------------------------

recoverySignal = detect bacterialRecoveryQC on bacterialEluate for 30s

// ============================================================
// BB2 / BB3: Recovery QC gate
// Pass (BB2): recoverySignal > 0 -> adequate bacterial yield
//             (>65% recovery); carry forward to lysis.
// Fail (BB3): recoverySignal <= 0 -> insufficient bacteria
//             recovered; drain and abort.
// Both branches converge at BB4 (recoveryJoin).
// ============================================================

if (recoverySignal > 0) {
    dispose bacterialEluate
} else {
    drain bacterialEluate
}

// ============================================================
// BB4: recoveryJoin
// Dispose recovery QC signal. Control falls into rRNA
// species identification branch (BB5/BB6).
// ============================================================

dispose recoverySignal

// ============================================================
// WORKFLOW 1: Species Identification via rRNA Detection
// ============================================================

// ------------------------------------------------------------
// STEP 6: Bacterial lysis for RNA extraction.
//   Concentrated pellet (50 uL in PBS) is lysed by vigorous
//   vortexing with 4x excess of RLT buffer (Qiagen) containing
//   beta-mercaptoethanol. Incubated 5 min at room temperature.
//   Lysate used immediately or stored at -80 C.
//   `heat` at 25 C models RT lysis incubation.
//   RLT buffer denatures proteins and inactivates RNases to
//   preserve RNA integrity for NanoString hybridization.
// ------------------------------------------------------------

bacterialPellet = dispense 1 units of WholeBlood

// Model: re-dispense of concentrated pellet as starting input.
// In practice this is the resuspended pellet from STEP 4.
rltBuffer        = dispense 1 units of RLT_Lysis_Buffer
bacterialLysate  = mix bacterialPellet with rltBuffer for 5m
heat bacterialLysate at 25c for 5m

// ------------------------------------------------------------
// STEP 7: NanoString rRNA hybridization for species ID.
//   Crude lysate input to NanoString assay. Two adjacent
//   50-nt probes hybridise to species-variable regions of
//   16S and 23S rRNA (>1000-fold more abundant than mRNA).
//   Probeset: 13 discriminatory probes targeting E. coli (Ec),
//   K. pneumoniae (Kp), P. aeruginosa (PsA), and Ec/Kp shared.
//   Hybridization time: 2 h (shortened from standard protocol
//   with minimal signal loss). PrepStation immobilises probes;
//   nCounter Digital Analyzer reads fluorescent barcodes.
//   Normalized Organism Score = geometric mean of
//   species-specific probe counts / sum of all geometric means.
//   Samples at 100 cfu/mL processed from 3 mL whole blood.
//   Hybridization modelled as `heat` at 65 C for 120 min.
//
//   NOTE: Direct detection from whole blood (without DFF)
//   produces uninterpretable hybridization patterns due to
//   interference from blood products. DFF pre-processing is
//   required for valid rRNA signal.
// ------------------------------------------------------------

heat bacterialLysate at 65c for 120m
rRNASignal = detect rRNASpeciesDetection on bacterialLysate for 30s

// ============================================================
// BB5 / BB6: rRNA species identification QC gate
// Pass (BB5): rRNASignal > 0 -> Organism Score assigns
//             species identity unambiguously; dispose lysate
//             and proceed to susceptibility workflow.
// Fail (BB6): rRNASignal <= 0 -> uninterpretable pattern
//             (e.g. insufficient bacterial load or mixed
//             infection outside probeset); drain.
// Both branches converge at BB7 (rRNAJoin).
// ============================================================

if (rRNASignal > 0) {
    dispose bacterialLysate
} else {
    drain bacterialLysate
}

// ============================================================
// BB7: rRNAJoin
// Dispose rRNA QC signal. Control falls into mRNA
// antibiotic susceptibility branch (BB8/BB9).
// ============================================================

dispose rRNASignal

// ============================================================
// WORKFLOW 2: Antibiotic Susceptibility via mRNA Detection
// ============================================================

// ------------------------------------------------------------
// STEP 8: Prepare bacteria at mRNA-detectable load.
//   Two input routes (both encoded here in sequence to
//   represent both experimental conditions in Fig. 5):
//
//   Route A (Direct spike): E. coli spiked at 10^5 cfu/mL
//     into 1 mL whole blood. Processed immediately by DFF.
//
//   Route B (Blood culture): BACTEC blood culture bottle
//     inoculated at 1 cfu/mL of E. coli; incubated 7.5 h at
//     37 C to reach >10^5 cfu/mL. Cultured blood then
//     processed by DFF (1:5 v/v dilution with culture media).
//     7.5 h = 450 min. `heat` models BACTEC incubation.
//
//   NOTE: NanoString mRNA detection requires ~10^5 cfu/mL,
//   which is >1 order of magnitude better than the VITEK-2
//   threshold (>10^6 cfu/mL) but exceeds typical bacteremia
//   loads (~10-100 cfu/mL). Blood culture pre-enrichment
//   bridges this gap while still being faster than current
//   gold-standard susceptibility methods.
//
//   Both susceptible and resistant isolates are encoded as
//   separate manifests; the Transcriptional Susceptibility
//   Score resolves their classification downstream.
// ------------------------------------------------------------

// Route A: Direct spike at 10^5 cfu/mL
ecoli_S          = dispense 1 units of EcoliClinicalIsolate_Susceptible
ecoli_R          = dispense 1 units of EcoliClinicalIsolate_Resistant

bloodForS        = dispense 1 units of WholeBlood
bloodForR        = dispense 1 units of WholeBlood

bufS1            = dispense 1 units of PBS_BSA_Buffer
bufS2            = dispense 1 units of PBS_BSA_Buffer
bufAccS          = mix bufS1 with bufS2 for 5s
dilutedBloodS    = mix bloodForS with bufAccS for 5s
spikedBloodS     = mix dilutedBloodS with ecoli_S for 5s

bufR1            = dispense 1 units of PBS_BSA_Buffer
bufR2            = dispense 1 units of PBS_BSA_Buffer
bufAccR          = mix bufR1 with bufR2 for 5s
dilutedBloodR    = mix bloodForR with bufAccR for 5s
spikedBloodR     = mix dilutedBloodR with ecoli_R for 5s

// Route B: Blood culture pre-enrichment (7.5 h at 37 C = 450 min)
// Modelled as heat step on the susceptible isolate sample.
// In practice, BACTEC bottle incubated off-chip before DFF.
heat spikedBloodS at 37c for 450m
heat spikedBloodR at 37c for 450m

// ------------------------------------------------------------
// STEP 9: DFF separation of bacteria from cultured blood.
//   Cultured blood (or directly spiked blood) processed
//   through the same spiral device at 1700 uL/min.
//   Bacteria at 10^5 cfu/mL are recovered at the bacterial
//   outlet with >65% efficiency. `mix` abstracts DFF event.
// ------------------------------------------------------------

sheathS          = dispense 1 units of SheathFluid
sheathR          = dispense 1 units of SheathFluid

eluateS          = mix spikedBloodS with sheathS for 20m
eluateR          = mix spikedBloodR with sheathR for 20m

// Concentrate bacterial eluates at RT (room temperature).
heat eluateS at 25c for 5m
heat eluateR at 25c for 5m

// ------------------------------------------------------------
// STEP 10: Ciprofloxacin exposure.
//   Concentrated bacterial fractions are exposed to
//   ciprofloxacin at 2.5 mcg/mL for 30 min at 37 C.
//   Ciprofloxacin (fluoroquinolone) inhibits DNA gyrase.
//   In susceptible organisms: transcriptional stress response
//   upregulates 6 ciprofloxacin-responsive mRNA transcripts.
//   In resistant organisms: these transcripts are not induced
//   at the same concentration. This differential expression
//   forms the basis of the Transcriptional Susceptibility Score.
//   30 min exposure is sufficient to generate a detectable
//   transcriptional signal without extensive bacterial growth.
// ------------------------------------------------------------

cipro_S          = dispense 1 units of Ciprofloxacin_Stock
cipro_R          = dispense 1 units of Ciprofloxacin_Stock

ciproExposure_S  = mix eluateS with cipro_S for 5s
ciproExposure_R  = mix eluateR with cipro_R for 5s

heat ciproExposure_S at 37c for 30m
heat ciproExposure_R at 37c for 30m

// ------------------------------------------------------------
// STEP 11: Lysis and NanoString mRNA detection.
//   Ciprofloxacin-exposed bacteria are lysed with RLT +
//   beta-mercaptoethanol (4x excess, 5 min RT).
//   NanoString probeset: 6 ciprofloxacin-responsive E. coli
//   mRNA transcripts + 3 control (non-responsive) transcripts.
//   Responsive transcripts normalised to the geometric mean
//   of control transcript expression to control for cell
//   number variation. Transcriptional Susceptibility Score
//   projected onto vector between centroid of susceptible
//   (score ~0) and resistant (score ~1) strains.
//   Hybridization: 2 h at 65 C.
//
//   NOTE: score <= 0 threshold (dashed line = 4 SD from
//   susceptible derivation cohort mean) identifies susceptible
//   isolates; score > 0 identifies resistant isolates.
//   mRNASusceptibilityDetection module abstracts this scoring.
// ------------------------------------------------------------

rltLysis_S       = dispense 1 units of RLT_Lysis_Buffer
rltLysis_R       = dispense 1 units of RLT_Lysis_Buffer

lysate_S         = mix ciproExposure_S with rltLysis_S for 5m
lysate_R         = mix ciproExposure_R with rltLysis_R for 5m

heat lysate_S at 25c for 5m
heat lysate_R at 25c for 5m

// NanoString mRNA hybridization: 2 h at 65 C
heat lysate_S at 65c for 120m
heat lysate_R at 65c for 120m

// Detect Transcriptional Susceptibility Score for each isolate.
// Score near 0: susceptible-like. Score near 1: resistant-like.
susceptibilitySignal_S = detect mRNASusceptibilityDetection on lysate_S for 30s
susceptibilitySignal_R = detect mRNASusceptibilityDetection on lysate_R for 30s

// ============================================================
// BB8 / BB9: Susceptibility classification gate
// The gate is keyed on susceptibilitySignal_S (susceptible
// isolate), which should score near 0 (signal <= 0 in the
// BioScript boolean sense = susceptible confirmed).
//
// Pass (BB8): susceptibilitySignal_S <= 0 -> score near 0,
//             susceptible-like transcriptional profile;
//             dispose both lysates.
// Fail (BB9): susceptibilitySignal_S > 0 -> score near 1,
//             resistant-like or ambiguous profile; drain both.
//
// NOTE: In the paper, both susceptible and resistant strains
// are clearly separated by the score (Fig. 5B). Here the
// gate logic reflects that a susceptible sample correctly
// classified has susceptibilitySignal_S <= 0. A resistant
// sample processed as lysate_S would fail this gate (> 0),
// correctly flagging resistance.
// ============================================================

if (susceptibilitySignal_S <= 0) {
    dispose lysate_S
    dispose lysate_R
} else {
    drain lysate_S
    drain lysate_R
}

// ============================================================
// BB10: finalCleanup (terminal)
// Dispose all susceptibility QC signal droplets.
// Experiment ends. Full workflow time: ~8 h including
// DFF separation (~20 min/mL), RNA hybridization (~2 h),
// and ciprofloxacin exposure (30 min).
// ============================================================

dispose susceptibilitySignal_S
dispose susceptibilitySignal_R

// [terminal -- no further instructions; exit node for CFG]

module beadFocusingQC
module ctcDetection

manifest PBS
manifest BSA_Solution
manifest Ethanol70
manifest SheathBuffer
manifest RBCLysisBuffer
manifest QCBeadSuspension
manifest LysedBloodSample
manifest Paraformaldehyde
manifest TritonX100
manifest PanCK_FITC_Antibody
manifest CD45_APC_Antibody
manifest HoechstDye

// ============================================================
// Ultra-fast, label-free isolation of circulating tumor cells
// from blood using spiral microfluidics.
// Warkiani, Khoo, Wu, Tay, Bhagat, Han, Lim
// Nature Protocols, Vol. 11, No. 1, pp. 134-148 (2016)
// DOI: 10.1038/nprot.2016.003
//
// Platform: spiral inertial microfluidic biochip (PDMS/glass).
// Channel dimensions: 500 um wide x 170 um deep, two-loop
// spiral, radius ~10 mm, two inlets (sample outer / sheath
// inner), two outlets (CTC inner / waste outer).
// Inlet split: 75 um sample / 425 um sheath.
// Outlet split: 150 um CTC collection / 350 um waste.
// Operating flow rates: sample 100 uL/min; sheath 750 uL/min
// (single chip). Multiplexed 3x chip: sheath 2100 uL/min.
//
// Separation physics: combined inertial lift force (FL) and
// Dean drag force (FD) in a curvilinear microchannel. CTCs
// (>15 um) focus near the inner wall; RBCs, WBCs, platelets
// (<15 um) migrate along Dean vortices toward outer wall.
// Dean number De = Re * sqrt(DH / 2*RC).
//
// Sample: 7.5 mL whole blood lysed with ammonium chloride RBC
// lysis buffer, resuspended 2x concentrated (~14e6 nucleated
// cells/mL in 3.75 mL PBS) before spiral processing.
// Throughput: 7.5 mL in 37.5 min (single), 12.5 min (3x).
// Performance: >=85% CTC recovery; 99.99% WBC depletion.
//
// NOTE ON FABRICATION ABSTRACTION: Steps 1-19 of the paper
// cover photolithography, DRIE, silanization, PDMS casting,
// soft lithography, and plasma bonding. These are off-chip
// physical fabrication steps that produce the spiral device.
// They are abstracted in BB1 as chip priming operations,
// consistent with BioScript conventions for prior protocols
// in this library. The first on-chip liquid handling step is
// chip priming (Step 20 onward in the paper procedure).
//
// NOTE ON SHEATH/SAMPLE DUAL-INLET: The spiral biochip has
// two independent inlets (sheath buffer inner, sample outer).
// BioScript `mix` abstracts the co-flow merging event at the
// spiral inlet where the two streams combine hydrodynamically.
// This is not a DMF droplet merge; it represents the inertial
// focusing run where sheath and sample enter the spiral channel
// together. The separation occurs passively along the channel
// length via inertial and Dean forces.
//
// NOTE ON QC BEAD CHECK: Step 27 in the paper runs 3-6 um
// polystyrene bead suspension (0.1% v/v) through the primed
// device to confirm particle focusing behavior before patient
// sample processing. The beadFocusingQC module abstracts the
// high-speed camera / phase-contrast microscope readout at
// the outlet region (inner wall focus = pass).
//
// NOTE ON IMMUNOFLUORESCENCE: Staining targets three markers:
//   pan-CK (FITC) -- epithelial marker; CTC positive
//   CD45 (APC)    -- leukocyte marker; CTC negative
//   Hoechst       -- nuclear stain; all nucleated cells
// Putative CTCs: pan-CK+, CD45-, Hoechst+, round nuclei,
// high nuclear-to-cytoplasmic ratio.
// Detection threshold (negative control): >7 CK+ cells/sample.
// ctcDetection module abstracts the fluorescence enumeration
// readout (Olympus IX71/81, ET460/50m / ET535/50m / ET605/70m
// filter set, automated MetaMorph stage scan, ImageJ threshold).
//
// NOTE ON DURATIONS: BioScript duration tokens are `s` and `m`
// only. All hour-based incubations are converted to minutes.
//   5 min priming      = 5m
//   10 min lysis       = 10m
//   37.5 min run       = 37m (single spiral, 7.5 mL lysed blood)
//   30-60 min staining = 30m (antibody incubation on ice)
//
// CFG STRUCTURE:
//   BB1  main           -- chip priming, bead QC, blood prep,
//                          spiral processing, cell collection
//   BB2  beadPass       -- beadSignal > 0: correct focusing,
//                          proceed to blood processing; dispose
//   BB3  beadFail       -- beadSignal <= 0: focusing incorrect
//                          (wrong channel depth or flow rate);
//                          drain bead suspension, abort run
//   BB4  beadJoin       -- join: blood prep and staining branch
//   BB5  ctcPass        -- ctcSignal > 0: CTC enumeration valid
//                          (>7 pan-CK+ cells); dispose all
//   BB6  ctcFail        -- ctcSignal <= 0: no CTCs detected
//                          (below threshold); drain stained cells
//   BB7  finalCleanup   -- terminal: dispose QC signal, end
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// CHIP PRIMING - STEP 1 (Paper Steps 20-22): Sterilize the
//   primed spiral biochip by flowing 70% (v/v) ethanol in
//   sterile deionized water for 5 min at 750 uL/min to
//   remove air bubbles and sterilize the channel interior.
//   Required for downstream cell culture applications.
//   NOTE: Chip fabrication (Steps 1-19: photolithography,
//   DRIE, silanization, PDMS soft lithography, plasma bonding)
//   is performed off-chip and is not encoded here.
// ------------------------------------------------------------

ethanolPrime = dispense 1 units of Ethanol70
channelWash  = mix ethanolPrime with ethanolPrime for 5m

// ------------------------------------------------------------
// CHIP PRIMING - STEP 2 (Paper Steps 23-25): Flush residual
//   ethanol and coat microchannel surfaces with sheath buffer
//   (1x sterile PBS + 0.5% w/v BSA) at 750 uL/min for 5 min.
//   BSA coating minimises non-specific cell adhesion to the
//   PDMS channel walls during spiral processing.
// ------------------------------------------------------------

bsaSolution    = dispense 1 units of BSA_Solution
sheathPriming  = dispense 1 units of SheathBuffer
surfaceCoating = mix bsaSolution with sheathPriming for 5m

// ------------------------------------------------------------
// CHIP PRIMING - STEP 3 (Paper Step 26): Inspect for bubbles
//   using inverted microscope (bright-field mode). Increasing
//   sheath flow rate dislodges residual air pockets.
//   Model as an additional sheath buffer flush.
// ------------------------------------------------------------

sheathFlush    = dispense 1 units of SheathBuffer
bubbleRemoval  = mix surfaceCoating with sheathFlush for 2m

// ------------------------------------------------------------
// QC BEAD CHECK (Paper Step 27): Load 3-6 um polystyrene bead
//   suspension (0.1% v/v) at 100 uL/min (sample inlet, outer
//   wall) co-flowing with sheath buffer at 750 uL/min (inner
//   inlet). Observe particle distribution across channel width
//   at outlet using phase-contrast microscope + high-speed
//   camera (VisionResearch Phantom v9).
//   Pass criterion: 6 um beads undergo complete Dean cycle
//   (inner -> outer wall migration visible); 15 um beads focus
//   tightly near inner wall at outlet.
//   NOTE: `mix` abstracts the co-flow hydrodynamic event at
//   the spiral inlet (not a DMF electrode merge).
// ------------------------------------------------------------

beadSuspension = dispense 1 units of QCBeadSuspension
sheathQC       = dispense 1 units of SheathBuffer
beadRun        = mix beadSuspension with sheathQC for 5m

beadSignal     = detect beadFocusingQC on beadRun for 30s

// ============================================================
// BB2 / BB3: Bead focusing QC gate
// Pass (BB2): beadSignal > 0 -> correct particle focusing
//             confirmed (channel depth 165-170 um verified);
//             dispose bead run and proceed to blood processing.
// Fail (BB3): beadSignal <= 0 -> incorrect focusing (channel
//             depth out of tolerance, <160 or >170 um due to
//             improper DRIE); drain, abort run, fabricate new
//             master mold (Table 1, Step 27 troubleshooting).
// Both branches converge at BB4 (beadJoin).
// ============================================================

if (beadSignal > 0) {
    dispose beadRun
} else {
    drain beadRun
}

// ============================================================
// BB4: beadJoin
// Dispose bead focusing QC signal. Control falls into the
// blood preparation and spiral processing branch.
// ============================================================

dispose beadSignal

// ------------------------------------------------------------
// BLOOD PREPARATION - STEP 1 (Paper Steps 28-29): Lyse RBCs
//   using 3x ammonium chloride RBC lysis buffer at 1:3 v/v
//   ratio. Invert conical tube to mix. Incubate 10 min at
//   room temperature (24-26 C) on shaking platform until
//   sample color changes to dark red (complete lysis).
//   NOTE: If spiking with cancer cell lines, cancer cells
//   must be added before lysis step (Reagent Setup in paper).
//   Lysis substantially reduces untargeted blood cells,
//   mitigating cell-cell interactions that impair inertial
//   focusing. Total cell loss from lysis + centrifugation <8%.
// ------------------------------------------------------------

rbcLysisBuffer = dispense 1 units of RBCLysisBuffer
lysedBlood1    = dispense 1 units of LysedBloodSample
lysisReaction  = mix lysedBlood1 with rbcLysisBuffer for 10m

// ------------------------------------------------------------
// BLOOD PREPARATION - STEP 2 (Paper Step 29): Pellet nucleated
//   cells by centrifugation at 1000g for 5 min at room temp.
//   Resuspend pellet in 1x PBS to 2x concentrated sample
//   (~14e6 nucleated cells/mL; 7.5 mL blood -> 3.75 mL PBS).
//   Model centrifugation as a heat step at room temperature.
// ------------------------------------------------------------

pbsResuspend   = dispense 1 units of PBS
heat lysisReaction at 25c for 5m
resuspendedSample = mix lysisReaction with pbsResuspend for 1m

// ------------------------------------------------------------
// SPIRAL PROCESSING (Paper Steps 32-37): Co-flow lysed blood
//   (100 uL/min, outer sample inlet) with sheath buffer
//   (750 uL/min, inner sheath inlet) through the two-loop
//   spiral biochip. CTCs (>15 um) focus near the inner wall
//   via inertial lift (FL) overcoming Dean drag (FD); smaller
//   blood cells (RBCs, WBCs, platelets, <15 um) exit from
//   the outer waste outlet following Dean vortex streamlines.
//   Total run: ~37 min for 7.5 mL lysed blood (single chip);
//   <13 min for 3x multiplexed chip (sheath 2100 uL/min).
//   CTC fraction collected from inner outlet into 15 mL tube.
//   NOTE: `mix` abstracts the hydrodynamic co-flow separation
//   event in the spiral channel. The CTCs continuously exit
//   from the inner outlet during this step; this is not a
//   discrete droplet merge but a continuous flow separation.
// ------------------------------------------------------------

sheathRun      = dispense 1 units of SheathBuffer
spiralRun      = mix resuspendedSample with sheathRun for 37m

// ------------------------------------------------------------
// CELL CONCENTRATION (Paper Step 38): Centrifuge collected CTC
//   fraction at 300g for 3 min at room temperature to pellet
//   cells and remove excess volume before staining.
//   Resuspend in ~250 uL PBS for downstream immunostaining.
//   Model centrifugation as a heat step at room temperature.
// ------------------------------------------------------------

heat spiralRun at 25c for 3m
pbsResuspend2       = dispense 1 units of PBS
concentratedCells   = mix spiralRun with pbsResuspend2 for 1m

// ------------------------------------------------------------
// IMMUNOFLUORESCENCE - STEP 1 (Paper Step 40): Fix cells with
//   4% w/v paraformaldehyde (PFA) in PBS for 10 min at room
//   temperature. PFA crosslinks cellular proteins to preserve
//   morphology and antigen epitopes for antibody staining.
//   CAUTION: PFA is a suspected carcinogen; handle with PPE.
// ------------------------------------------------------------

pfaFixative  = dispense 1 units of Paraformaldehyde
fixedCells   = mix concentratedCells with pfaFixative for 10m

// ------------------------------------------------------------
// IMMUNOFLUORESCENCE - STEP 2 (Paper Step 41): Wash fixed
//   cells with 1-2 mL PBS + 0.5% w/v BSA, centrifuge at
//   300g for 3 min at room temperature to remove residual PFA.
//   Resuspend in ~250 uL PBS before permeabilization.
// ------------------------------------------------------------

bsaWash1     = dispense 1 units of BSA_Solution
pbsWash1     = dispense 1 units of PBS
washBuffer1  = mix bsaWash1 with pbsWash1 for 30s
heat washBuffer1 at 25c for 3m
washedFixed  = mix fixedCells with washBuffer1 for 1m

// ------------------------------------------------------------
// IMMUNOFLUORESCENCE - STEP 3 (Paper Step 42): Permeabilize
//   cells with 0.1% v/v Triton X-100 in PBS for 1-5 min at
//   room temperature. Triton X-100 solubilizes the plasma
//   membrane to allow intracellular antibody access for
//   pan-cytokeratin (pan-CK) staining of the cytoskeleton.
// ------------------------------------------------------------

tritonX100     = dispense 1 units of TritonX100
permeaCells    = mix washedFixed with tritonX100 for 3m

// ------------------------------------------------------------
// IMMUNOFLUORESCENCE - STEP 4 (Paper Step 43): Wash
//   permeabilized cells with 1-2 mL PBS + 0.5% w/v BSA,
//   centrifuge at 300g for 3 min at room temperature to
//   remove Triton X-100 before antibody incubation.
// ------------------------------------------------------------

bsaWash2     = dispense 1 units of BSA_Solution
pbsWash2     = dispense 1 units of PBS
washBuffer2  = mix bsaWash2 with pbsWash2 for 30s
heat washBuffer2 at 25c for 3m
washedPermea = mix permeaCells with washBuffer2 for 1m

// ------------------------------------------------------------
// IMMUNOFLUORESCENCE - STEP 5 (Paper Step 44): Incubate cells
//   on ice with conjugated antibody cocktail for 30 min:
//     - FITC pan-cytokeratin (pan-CK) 1:100 -- CTC marker
//       (CK8, CK9, CK18, CK19; epithelial cytokeratins).
//       Miltenyi Biotec Asia Pacific. Excitation 490 nm,
//       emission 526 nm.
//     - APC CD45 1:100 -- leukocyte marker (WBC counter-stain
//       to exclude contaminating WBCs from CTC count).
//       Miltenyi Biotec Asia Pacific.
//     - Hoechst 33342 1:1000 (1 M stock) -- nuclear stain
//       for all nucleated cells; confirms CTC nuclei.
//   Putative CTCs: pan-CK+, CD45-, Hoechst+, round nuclei,
//   high nuclear-to-cytoplasmic (N/C) ratio.
//   Incubation on ice prevents antigen internalization and
//   non-specific binding. Model as heat at 4c for 30m.
// ------------------------------------------------------------

panCKAntibody  = dispense 1 units of PanCK_FITC_Antibody
cd45Antibody   = dispense 1 units of CD45_APC_Antibody
hoechstDye     = dispense 1 units of HoechstDye

antibodyMix    = mix panCKAntibody with cd45Antibody for 5s
fullStainMix   = mix antibodyMix with hoechstDye for 5s
stainedCells   = mix washedPermea with fullStainMix for 30m
heat stainedCells at 4c for 30m

// ------------------------------------------------------------
// IMMUNOFLUORESCENCE - STEP 6 (Paper Step 45): Wash stained
//   cells with 1-2 mL PBS + 0.5% w/v BSA, centrifuge at
//   300g for 3 min to remove unbound antibody. Resuspend in
//   ~250 uL PBS and transfer to a single 96-well plate well.
// ------------------------------------------------------------

bsaWash3      = dispense 1 units of BSA_Solution
pbsWash3      = dispense 1 units of PBS
washBuffer3   = mix bsaWash3 with pbsWash3 for 30s
heat washBuffer3 at 25c for 3m
washedStained = mix stainedCells with washBuffer3 for 1m

pbsFinal      = dispense 1 units of PBS
finalCells    = mix washedStained with pbsFinal for 30s

// ------------------------------------------------------------
// CTC DETECTION (Paper Step 47): Fluorescence enumeration of
//   pan-CK+/CD45-/Hoechst+ cells with round nuclei and high
//   N/C ratio. Platform: Olympus inverted microscope (IX71/81)
//   with phase-contrast, emission filters ET460/50m (Hoechst),
//   ET535/50m (pan-CK FITC), ET605/70m (CD45 APC); automated
//   stage (MetaMorph); 12-bit EM-CCD camera (Andor iXon+885).
//   Each 96-well plate well scanned in 1x1 mm grid.
//   Threshold: >7 CK+ cells per sample = positive patient.
//   Clinical range: 12-1275 CK+ breast CTCs; 10-1535 lung CTCs.
//   ctcDetection module abstracts the fluorescence readout and
//   cell classification step.
// ------------------------------------------------------------

ctcSignal = detect ctcDetection on finalCells for 45m

// ============================================================
// BB5 / BB6: CTC detection gate
// Pass (BB5): ctcSignal > 0 -> pan-CK+/CD45-/Hoechst+ cells
//             enumerated above threshold (>7 CK+ cells);
//             positive patient sample confirmed. Dispose.
// Fail (BB6): ctcSignal <= 0 -> no CTCs detected above
//             threshold (healthy donor control or run failure);
//             drain stained cells.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (ctcSignal > 0) {
    dispose finalCells
} else {
    drain finalCells
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose CTC detection QC signal. Experiment ends.
// Downstream options for recovered CTCs (from inner outlet
// collected prior to staining): culture (37 C / 5% CO2),
// DNA/RNA-FISH (ALK break-apart probe, HER2/neu), KRAS
// codon 12 mutation by ICE-COLD PCR + Sanger sequencing,
// single-cell analysis. These are encoded as separate protocols.
// ============================================================

dispose ctcSignal

// [terminal -- no further instructions; exit node for CFG]

module fluorescence

// Reagents used in the DMF-LAMP c-Myc amplification protocol
// (Coelho et al., Sensors 2017, 17, 2616)
manifest LAMPMix
manifest DNASample

instructions:

// --- Reagent dispensing and transport ---
// 10 droplets of LAMP reagents (~0.14 uL/droplet -> ~1.40 uL total)
// dispensed from the left reservoir
reagent = dispense 10 units of LAMPMix

// 1 droplet of target DNA sample (~0.14 uL) dispensed from the
// right reservoir, giving a final 0.5 ng/uL DNA concentration
sample = dispense 1 units of DNASample

// --- Merging and mixing in the central reaction reservoir ---
// Total on-chip reaction volume: 1.54 uL
LAMP_Reaction = mix reagent with sample

// --- Isothermal amplification at the bottom-plate set point (65C) ---
// LAMP is isothermal, so there is no thermal cycling as in PCR;
// amplification efficiency was evaluated in 15 min increments
// (15 min, 30 min, 45 min) per Figure 3e

heat LAMP_Reaction at 65c for 15m
Amp_Check_15 = detect fluorescence on LAMP_Reaction for 30s

if (Amp_Check_15 <= 80) {

    heat LAMP_Reaction at 65c for 15m
    Amp_Check_30 = detect fluorescence on LAMP_Reaction for 30s

    if (Amp_Check_30 <= 80) {

        heat LAMP_Reaction at 65c for 15m
        Amp_Check_45 = detect fluorescence on LAMP_Reaction for 30s

        if (Amp_Check_45 <= 80) {
            dispose LAMP_Reaction
        }
    }
}

// --- Reaction product transport for withdrawal ---
// Successful amplification (positive signal at/after 45 min total)
// is routed to the retrieving reservoir; product is withdrawn
// from the device via pipette
dispose LAMP_Reaction

module iemSensorDetection
module sawLysingDetection
module miR21FreefloatingDetection
module miR21TotalDetection

manifest Plasma_Sample
manifest PBS_1x
manifest PBS_4x
manifest PBS_01x
manifest TAE_Buffer_10x
manifest miR21_OligoProbe
manifest SAW_Actuator
manifest IEM_AEM_Sensor
manifest IEM_CEM_Concentrator

instructions:

// ============================================================
// Extracellular Vesicle microRNA Quantification from Plasma
// Using an Integrated Microfluidic Device
// Ramshani et al., Communications Biology (2019) 2:189
// DOI: 10.1038/s42003-019-0435-1
//
// Protocol: PCR-free absolute quantification of free-floating
// and EV-contained miR-21 from untreated human plasma using
// (1) a surface acoustic wave (SAW) lysing chip that
//     mechanically lyses EVs under continuous flow, and
// (2) a concentration/sensing chip with ion-exchange
//     membranes (IEMs) that concentrate and detect
//     target miRNA via current-voltage curve (CVC) shift.
//
// Biomarker: miRNA hsa-mir-21-5p (miR-21)
//   Sequence: TAGCTTATCAGACTGATGTTGA
//   Correlation: pancreatic cancer, lung cancer,
//                colorectal cancer, hepatocellular carcinoma.
//
// Key specs:
//   Sample volume   : ~20 uL per measurement (40 uL total)
//   Assay time      : ~30 min per measurement (~60 min total)
//   Detection limit : 1 pM
//   Quantification  : <10% uncertainty (absolute, PCR-free)
//   SAW frequency   : 28 MHz, 1 W
//   SAW flow rate   : 250 uL/h
//   EV lysis time   : ~1 min in SAW channel
//   Concentration V : 200 V DC for 20 min
//   Hybridisation   : 20 min (concurrent with concentration)
//   Wash buffer     : 4x PBS (post-hybridisation)
//   CVC buffer      : 0.1x PBS (measurement)
//
// NOTE ON IEM SENSOR ABSTRACTION:
//   The AEM sensor is functionalized with a complementary
//   ssDNA oligoprobe (TCAACATCAGTCTGATAAGCTA) to miR-21.
//   Target hybridisation shifts the over-limiting region of
//   the CVC by Delta-V (V), which is log-linearly correlated
//   to miR-21 concentration:
//     C (nM) = exp((Delta-V - 0.76145) / 0.06614)
//   `detect iemSensorDetection` abstracts the CVC sweep
//   (Gamry 500 potentiostat, Ag-AgCl reference electrodes).
//   `detect sawLysingDetection` abstracts SAW actuation
//   and confirms lysis before downstream sensing.
//   `detect miR21FreefloatingDetection` abstracts CVC shift
//   measurement for the unlysed (free-floating) plasma run.
//   `detect miR21TotalDetection` abstracts CVC shift
//   measurement for the SAW-lysed (total miRNA) plasma run.
//
// NOTE ON CONCENTRATION STEP ABSTRACTION:
//   Application of 200 V DC across the CEM reservoir for
//   20 min creates an ion-depletion zone upstream of the
//   AEM sensor, concentrating negatively charged miRNA
//   by up to three orders of magnitude directly beneath
//   the sensor where hybridisation occurs. This is modelled
//   as a `heat` step at 25c (room temperature) for 20 min
//   (= 1200 s), reflecting the ambient temperature of the
//   concentration/sensing chip during IEM operation.
//
// CFG STRUCTURE:
//   BB1  main                  -- device setup, IEM baseline CVC,
//                                  free-floating miR-21 measurement
//   BB2  freefloatingPass      -- freefloatSignal > 0: valid
//                                  free-floating miR-21 detected;
//                                  proceed to SAW-lysed total run
//   BB3  freefloatingFail      -- freefloatSignal <= 0: no signal
//                                  (below sensor limit); drain
//   BB4  freefloatingJoin      -- join: total miRNA measurement begins
//   BB5  totalPass             -- totalSignal > 0: valid total miR-21
//                                  (free-floating + EV-miRNA) detected;
//                                  dispose and compute EV fraction
//   BB6  totalFail             -- totalSignal <= 0: no total signal;
//                                  drain
//   BB7  finalCleanup          -- terminal: dispose QC signals,
//                                  experiment ends
// ============================================================

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prepare 1x PBS running buffer and establish
//         baseline CVC on the IEM sensor (oligoprobe only,
//         no sample). The sensor is functionalized prior to
//         use with miR-21 complementary ssDNA oligoprobe
//         (TCAACATCAGTCTGATAAGCTA) via standard amine-
//         coupling on the AEM surface.
//         This baseline CVC (miR-21 probe in 1x PBS only)
//         is used as the reference for all Delta-V measurements.
//         Buffer volume: 60 uL (used as driver fluid after
//         sample injection throughout the protocol).
// ------------------------------------------------------------

runningBuffer   = dispense 1 units of PBS_1x
probeBaseline   = dispense 1 units of IEM_AEM_Sensor

baselineMix     = mix runningBuffer with probeBaseline for 5s
baselineSignal  = detect iemSensorDetection on baselineMix for 30s

// ------------------------------------------------------------
// STEP 2: MEASUREMENT 1 - Free-floating miR-21 quantification.
//         ~20 uL of untreated human plasma is injected into
//         the integrated platform with the SAW device OFF
//         (no EV lysis). The sample passes through the lysing
//         chip channel and flows directly into the
//         concentration/sensing chip.
//         Flow rate: 250 uL/h (sample + 60 uL PBS driver).
//         The SAW chip channel is bypassed acoustically
//         (IDT powered off) -- EVs remain intact.
//         Only free-floating miR-21 present in plasma reaches
//         the IEM sensor.
//         NOTE: `mix` here abstracts continuous flow injection
//         through the microfluidic channel; no DMF-style
//         droplet merging occurs. Plasma is used as-is with
//         no sample preparation.
// ------------------------------------------------------------

plasmaRun1      = dispense 1 units of Plasma_Sample
driverBuffer1   = dispense 1 units of PBS_1x

// Continuous-flow channel injection (SAW OFF - no lysis).
// Flow carries 20 uL plasma + 60 uL PBS driver at 250 uL/h.
channelFlow1    = mix plasmaRun1 with driverBuffer1 for 2s

// ------------------------------------------------------------
// STEP 3: IEM concentration - apply 200 V DC across CEM
//         reservoir for 20 min. The resulting depletion zone
//         concentrates negatively charged free-floating
//         miR-21 upstream of the AEM sensor surface.
//         Hybridisation with the oligoprobe occurs
//         concurrently during this 20-min window.
//         Modelled as room-temperature incubation (25 C,
//         20 min = 1200 s) to represent non-thermal IEM
//         electrokinetic concentration at ambient conditions.
// ------------------------------------------------------------

cemConcentrator1 = dispense 1 units of IEM_CEM_Concentrator
concentrating1   = mix channelFlow1 with cemConcentrator1 for 1200s

// IEM electrokinetic concentration at ambient temperature.
heat concentrating1 at 25c for 1200s

// ------------------------------------------------------------
// STEP 4: Post-hybridisation wash with 4x PBS to remove
//         non-hybridised species from the AEM sensor surface.
//         Then pump 0.1x PBS into the channel prior to the
//         CVC measurement sweep.
// ------------------------------------------------------------

washBuffer1     = dispense 1 units of PBS_4x
washed1         = mix concentrating1 with washBuffer1 for 2s

cvcBuffer1      = dispense 1 units of PBS_01x
readyForCVC1    = mix washed1 with cvcBuffer1 for 2s

// ------------------------------------------------------------
// STEP 5: CVC sweep - measure Delta-V for free-floating
//         miR-21. Concentration voltage is terminated;
//         Gamry 500 potentiostat applies current-voltage
//         sweep (0 to 2.5 V) between the AEM sensor reservoir
//         and upstream reservoir via platinum electrodes.
//         Voltage drop measured by Ag-AgCl reference electrodes
//         across the sensor. Delta-V in the over-limiting
//         current region is recorded.
//         miR21FreefloatingDetection abstracts this CVC sweep
//         and returns a positive signal if Delta-V > sensor
//         noise floor (> ~0.1 V for free-floating miR-21
//         in healthy human plasma as per paper Fig. 3).
// ------------------------------------------------------------

freefloatSignal = detect miR21FreefloatingDetection on readyForCVC1 for 30s

// ============================================================
// BB2 / BB3: Free-floating miR-21 QC gate
// Pass (BB2): freefloatSignal > 0 -> measureable Delta-V
//             detected for free-floating miR-21; dispose
//             and proceed to SAW-lysed total measurement.
// Fail (BB3): freefloatSignal <= 0 -> signal below sensor
//             noise floor (< 1 pM); drain and abort.
// Both branches converge at BB4 (freefloatingJoin).
// ============================================================

if (freefloatSignal > 0) {
    dispose readyForCVC1
} else {
    drain readyForCVC1
}

// ============================================================
// BB4: freefloatingJoin
// Dispose free-floating QC signal. Control falls into
// total miRNA measurement branch (BB5/BB6).
// ============================================================

dispose freefloatSignal
dispose baselineSignal

// ------------------------------------------------------------
// STEP 6: MEASUREMENT 2 - Total miR-21 quantification
//         (free-floating + EV-contained miR-21).
//         A fresh 20 uL aliquot of the same plasma sample is
//         injected with the SAW device ACTIVE (28 MHz, 1 W).
//         SAWs refract into the polycarbonate microchannel
//         perpendicular to the IDT array, generating acoustic
//         pressure that mechanically shears EVs open.
//         Residence time: ~1 min in the SAW channel at
//         250 uL/h flow rate -- sufficient for ~100% EV lysis.
//         Released EV-miRNA and free-floating miRNA both
//         flow into the concentration/sensing chip.
//         NOTE: `mix` abstracts SAW channel flow-through.
//         sawLysingDetection confirms acoustic lysis before
//         the lysate enters the IEM chip.
// ------------------------------------------------------------

sawActuator     = dispense 1 units of SAW_Actuator
plasmaRun2      = dispense 1 units of Plasma_Sample
driverBuffer2   = dispense 1 units of PBS_1x

// SAW lysis: 28 MHz, 1 W, ~1 min exposure at 250 uL/h.
// NOTE: `mix` abstracts the channel-flow EV lysis event.
// No DMF electrode mixing occurs; this models acoustic
// pressure shearing of EV membranes under continuous flow.
sawLysate       = mix plasmaRun2 with sawActuator for 60s

// Detect lysis completion (confirms EVs are mechanically
// disrupted before lysate enters concentration/sensing chip).
lysisSignal     = detect sawLysingDetection on sawLysate for 10s

// Flow lysate into concentration/sensing chip under PBS driver.
channelFlow2    = mix sawLysate with driverBuffer2 for 2s

// ------------------------------------------------------------
// STEP 7: IEM concentration - second run.
//         200 V DC applied for 20 min across CEM reservoir.
//         Both free-floating miR-21 and EV-released miR-21
//         (total pool) concentrate upstream of the AEM sensor
//         and hybridise with the miR-21 oligoprobe.
//         IEM sensor is replaced (disposable) between runs
//         to maintain optimised repeatability.
// ------------------------------------------------------------

cemConcentrator2 = dispense 1 units of IEM_CEM_Concentrator
concentrating2   = mix channelFlow2 with cemConcentrator2 for 1200s

// IEM electrokinetic concentration at ambient temperature.
heat concentrating2 at 25c for 1200s

// ------------------------------------------------------------
// STEP 8: Post-hybridisation wash and buffer exchange
//         for the total miRNA CVC measurement.
//         4x PBS wash removes non-hybridised species.
//         0.1x PBS is pumped in before the CVC sweep.
// ------------------------------------------------------------

washBuffer2     = dispense 1 units of PBS_4x
washed2         = mix concentrating2 with washBuffer2 for 2s

cvcBuffer2      = dispense 1 units of PBS_01x
readyForCVC2    = mix washed2 with cvcBuffer2 for 2s

// ------------------------------------------------------------
// STEP 9: CVC sweep - measure Delta-V for total miR-21
//          (free-floating + EV-miRNA).
//          Same potentiostat procedure as STEP 6.
//          Expected Delta-V for total miR-21 in healthy human
//          plasma: ~0.65-0.7 V (vs ~0.1 V for free-floating
//          only) as per paper Fig. 3.
//          The difference in voltage shift between Measurement
//          1 (free-floating) and Measurement 2 (total)
//          directly quantifies the EV-miR-21 fraction.
//          EV-miR-21 concentration is calculated from the
//          calibration curve: C = exp((Delta-V - 0.76145) / 0.06614)
//          miR21TotalDetection abstracts this CVC sweep and
//          returns positive signal if Delta-V significantly
//          exceeds the free-floating baseline (> ~0.2 V shift
//          from free-floating run expected for EV contribution).
// ------------------------------------------------------------

totalSignal     = detect miR21TotalDetection on readyForCVC2 for 30s

// ============================================================
// BB5 / BB6: Total miR-21 QC gate
// Pass (BB5): totalSignal > 0 -> measurable Delta-V for
//             total miR-21 detected; Delta-V > free-floating
//             signal confirming EV-miRNA released by SAW.
//             Dispose all droplets and proceed to cleanup.
// Fail (BB6): totalSignal <= 0 -> no total signal (SAW lysis
//             failure or IEM sensor issue); drain all.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (totalSignal > 0) {
    dispose readyForCVC2
    dispose lysisSignal
} else {
    drain readyForCVC2
    drain lysisSignal
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose all remaining QC signal droplets.
// The EV-miR-21 expression level is computed off-chip by
// comparing the two voltage shifts using:
//   ExpressionLevel = exp((Delta-V_total - Delta-V_freefloat) / b)
// where b = 0.06614 is the log-linear calibration fitting
// parameter from the IEM sensor calibration curve (Fig. 2b).
// Experiment ends.
// ============================================================

dispose totalSignal
dispose baselineMix

// [terminal -- no further instructions; exit node for CFG]

module speExtractionDetection
module fluorescenceDetection
module massSpecDetection

manifest ActivationSolvent
manifest EquilibrationSolvent
manifest WashSolvent
manifest ElutionSolvent
manifest MonomersC12
manifest FluoresceinSample
manifest PeptideSample
manifest AngiotensinII_NaCl
manifest AngiotensinII_Pluronic
manifest PluronicF68

// ============================================================
// A Digital Microfluidic Method for in Situ Formation of
// Porous Polymer Monoliths with Application to Solid-Phase
// Extraction.
// Yang, Mudrik, Jebrail, Wheeler - Anal. Chem. 2011, 83, 3824-3830.
// DOI: 10.1021/ac2002388
//
// Three sequential protocols encoded:
//
// PROTOCOL 1+2: PPM disc formation + standard DMF-SPE.
//   PPM formed by dispensing 1 uL C12 casting solution, driving
//   to centre electrode, UV-polymerizing (100 W, 365 nm, 5 min;
//   abstracted as heat at 25c for 5m). Disc: radius ~1 mm,
//   height 270 um, SSA 3.7 +/- 0.2 m2/g. Four-step SPE:
//   activation / equilibration / sample load / wash / elution.
//   Validated efficiency: 93 +/- 14% (n=3). Model analyte:
//   fluorescamine-labeled angiotensin IV (10 uM, 0.1% FA).
//
// PROTOCOL 3a: Preparative DMF-SPE -- desalting.
//   Sample: Ang II (1 uM) in 100 mM NaCl -> nanoESI-MS.
//   [M+H]+ at m/z 1047 recovered after SPE (Fig. 4a).
//
// PROTOCOL 3b: Preparative DMF-SPE -- surfactant removal.
//   Sample: Ang II (1 uM) in 0.05% w/v Pluronic F68 -> nanoESI-MS.
//   [M+H]+ at m/z 1047 recovered after SPE (Fig. 4b).
//
// FIX #1 -- heat is void in lilott8/BioScript:
//   `heat var at Tc for Td` mutates var in place and returns
//   nothing. Aliasing after heat (e.g. ppmDisc = centredDroplet)
//   creates an undefined token. Fix: use the heated variable
//   directly (centredDroplet / disc2 / disc3) without aliasing.
//
// FIX #2 -- each protocol consumes its PPM disc:
//   Protocol 2 drives solvents/sample through centredDroplet
//   via sequential mix ops, leaving it consumed. Protocols 3a
//   and 3b each form their own independent PPM disc (disc2,
//   disc3) via a fresh dispense + mix + heat sequence.
//
// NOTE ON mix FOR TRANSLATION: BioScript requires two operands
//   for mix. The physical droplet translation step (driving the
//   monomer droplet to the centre electrode) has no second
//   reagent. A second dispense of the same monomer is used as
//   the required second operand; no chemical change occurs.
//
// NOTE ON heat FOR UV EXPOSURE: No UV primitive exists in
//   BioScript. 100 W / 365 nm / 5 min UV polymerization is
//   abstracted as heat at 25c for 5m (isothermal hold).
//
// CFG STRUCTURE:
//   BB1  main           -- disc1 formation + Protocol 2 DMF-SPE
//   BB2  spePass        -- speSignal > 0: dispose eluate
//   BB3  speFail        -- speSignal <= 0: drain eluate
//   BB4  speJoin        -- disc2 formation + Protocol 3a
//   BB5  desaltPass     -- desaltSignal > 0: dispose eluate
//   BB6  desaltFail     -- desaltSignal <= 0: drain eluate
//   BB7  desaltJoin     -- disc3 formation + Protocol 3b
//   BB8  surfactantPass -- surfactantSignal > 0: dispose eluate
//   BB9  surfactantFail -- surfactantSignal <= 0: drain eluate
//   BB10 finalCleanup   -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// PROTOCOL 1 -- PPM disc 1 formation.
//   Dispense 1 uL C12 casting solution; translate to centre
//   electrode via actuation (mix models translation; second
//   dispense of same monomer satisfies two-operand requirement);
//   UV-polymerize (heat at 25c for 5m abstracts UV step).
//   FIX #1: centredDroplet used directly after heat; no alias.
// ------------------------------------------------------------

monomer1a      = dispense 1 units of MonomersC12
monomer1b      = dispense 1 units of MonomersC12
centredDroplet = mix monomer1a with monomer1b for 10s
heat centredDroplet at 25c for 5m

// ============================================================
// PROTOCOL 2: Standard four-step DMF-SPE
// ============================================================

// Step 1a: Activation (0.1% v/v FA in ACN; 5 uL; 5x pass; 1 min)
activationSolvent1    = dispense 1 units of ActivationSolvent
activatedDisc1        = mix centredDroplet with activationSolvent1 for 1m
dispose activationSolvent1

// Step 1b: Equilibration (0.5% v/v FA in H2O; 5 uL; 5x pass; 1 min)
equilibrationSolvent1 = dispense 1 units of EquilibrationSolvent
equilibratedDisc1     = mix activatedDisc1 with equilibrationSolvent1 for 1m
dispose equilibrationSolvent1

// Step 2: Sample loading (1 uL; 5x pass; 2 min incubation).
//   2 min optimized (Fig. 3a: >80% bound; p=0.30 vs 4 min).
peptideSample1 = dispense 1 units of PeptideSample
loadedDisc1    = mix equilibratedDisc1 with peptideSample1 for 2m
dispose peptideSample1

// Step 3: Washing (2 x 5 uL; 0.5% v/v FA in H2O)
washSolvent1a  = dispense 1 units of WashSolvent
washedDisc1a   = mix loadedDisc1 with washSolvent1a for 30s
dispose washSolvent1a

washSolvent1b  = dispense 1 units of WashSolvent
washedDisc1b   = mix washedDisc1a with washSolvent1b for 30s
dispose washSolvent1b

// Step 4: Elution (2 x 5 uL; 0.1% v/v FA in ACN).
//   2 droplets optimized (Fig. 3b: >90% extracted; p=0.25 vs 3).
elutionSolvent1a = dispense 1 units of ElutionSolvent
eluate1a         = mix washedDisc1b with elutionSolvent1a for 30s

elutionSolvent1b = dispense 1 units of ElutionSolvent
eluate1b         = mix eluate1a with elutionSolvent1b for 30s

speSignal = detect speExtractionDetection on eluate1b for 30s

// ============================================================
// BB2 / BB3: Standard DMF-SPE QC gate
// Pass (BB2): speSignal > 0 -> valid extraction; dispose.
// Fail (BB3): speSignal <= 0 -> extraction failed; drain.
// Both branches converge at BB4 (speJoin).
// ============================================================

if (speSignal > 0) {
    dispose eluate1b
} else {
    drain eluate1b
}

// ============================================================
// BB4: speJoin
// Dispose SPE QC signal. Form disc 2 for Protocol 3a.
// FIX #2: disc 2 is fresh; centredDroplet was consumed above.
// ============================================================

dispose speSignal

// ============================================================
// PROTOCOL 3a: Preparative DMF-SPE -- Desalting
// Sample: Ang II (1 uM) in 100 mM NaCl. [M+H]+ m/z 1047
// absent without SPE (ion suppression); recovered after SPE.
// nanoESI-MS: LTQ Finnigan, 1.7-2.0 kV, 0.5 uL/min, 200 C.
// ============================================================

// Form PPM disc 2 (FIX #2: independent of disc 1)
monomer2a = dispense 1 units of MonomersC12
monomer2b = dispense 1 units of MonomersC12
disc2     = mix monomer2a with monomer2b for 10s
heat disc2 at 25c for 5m

// Step 1a: Activation
activationSolvent2    = dispense 1 units of ActivationSolvent
activatedDisc2        = mix disc2 with activationSolvent2 for 1m
dispose activationSolvent2

// Step 1b: Equilibration
equilibrationSolvent2 = dispense 1 units of EquilibrationSolvent
equilibratedDisc2     = mix activatedDisc2 with equilibrationSolvent2 for 1m
dispose equilibrationSolvent2

// Step 2: Sample loading (Ang II + 100 mM NaCl; 2 min)
angII_NaCl_Sample = dispense 1 units of AngiotensinII_NaCl
loadedDisc2       = mix equilibratedDisc2 with angII_NaCl_Sample for 2m
dispose angII_NaCl_Sample

// Step 3: Washing
washSolvent2a = dispense 1 units of WashSolvent
washedDisc2a  = mix loadedDisc2 with washSolvent2a for 30s
dispose washSolvent2a

washSolvent2b = dispense 1 units of WashSolvent
washedDisc2b  = mix washedDisc2a with washSolvent2b for 30s
dispose washSolvent2b

// Step 4: Elution (2 x; pooled -> nanoESI-MS)
desaltElution1 = dispense 1 units of ElutionSolvent
desaltEluate1  = mix washedDisc2b with desaltElution1 for 30s

desaltElution2 = dispense 1 units of ElutionSolvent
desaltEluate2  = mix desaltEluate1 with desaltElution2 for 30s

desaltSignal = detect massSpecDetection on desaltEluate2 for 30s

// ============================================================
// BB5 / BB6: Desalting QC gate
// Pass (BB5): desaltSignal > 0 -> m/z 1047 detected; dispose.
// Fail (BB6): desaltSignal <= 0 -> suppression persists; drain.
// Both branches converge at BB7 (desaltJoin).
// ============================================================

if (desaltSignal > 0) {
    dispose desaltEluate2
} else {
    drain desaltEluate2
}

// ============================================================
// BB7: desaltJoin
// Dispose desalting QC signal. Form disc 3 for Protocol 3b.
// FIX #2: disc 3 is fresh; disc 2 was consumed above.
// ============================================================

dispose desaltSignal

// ============================================================
// PROTOCOL 3b: Preparative DMF-SPE -- Surfactant Removal
// Sample: Ang II (1 uM) in 0.05% w/v Pluronic F68.
// Pluronics: strong nanoESI suppressors (paper refs 47-48).
// [M+H]+ at m/z 1047 recovered after DMF-SPE (Fig. 4b).
// ============================================================

// Form PPM disc 3 (FIX #2: independent of disc 2)
monomer3a = dispense 1 units of MonomersC12
monomer3b = dispense 1 units of MonomersC12
disc3     = mix monomer3a with monomer3b for 10s
heat disc3 at 25c for 5m

// Step 1a: Activation
activationSolvent3    = dispense 1 units of ActivationSolvent
activatedDisc3        = mix disc3 with activationSolvent3 for 1m
dispose activationSolvent3

// Step 1b: Equilibration
equilibrationSolvent3 = dispense 1 units of EquilibrationSolvent
equilibratedDisc3     = mix activatedDisc3 with equilibrationSolvent3 for 1m
dispose equilibrationSolvent3

// Step 2: Sample loading (Ang II + 0.05% Pluronic F68; 2 min)
angII_Pluronic_Sample = dispense 1 units of AngiotensinII_Pluronic
loadedDisc3           = mix equilibratedDisc3 with angII_Pluronic_Sample for 2m
dispose angII_Pluronic_Sample

// Step 3: Washing
washSolvent3a = dispense 1 units of WashSolvent
washedDisc3a  = mix loadedDisc3 with washSolvent3a for 30s
dispose washSolvent3a

washSolvent3b = dispense 1 units of WashSolvent
washedDisc3b  = mix washedDisc3a with washSolvent3b for 30s
dispose washSolvent3b

// Step 4: Elution (2 x; pooled -> nanoESI-MS)
surfActElution1 = dispense 1 units of ElutionSolvent
surfActEluate1  = mix washedDisc3b with surfActElution1 for 30s

surfActElution2 = dispense 1 units of ElutionSolvent
surfActEluate2  = mix surfActEluate1 with surfActElution2 for 30s

surfactantSignal = detect massSpecDetection on surfActEluate2 for 30s

// ============================================================
// BB8 / BB9: Surfactant removal QC gate
// Pass (BB8): surfactantSignal > 0 -> m/z 1047 detected;
//             Pluronic F68 removed; dispose eluate.
// Fail (BB9): surfactantSignal <= 0 -> suppression persists;
//             drain eluate.
// Both branches converge at BB10 (finalCleanup).
// ============================================================

if (surfactantSignal > 0) {
    dispose surfActEluate2
} else {
    drain surfActEluate2
}

// ============================================================
// BB10: finalCleanup (terminal)
// Dispose all remaining QC signal droplets. Experiment ends.
// ============================================================

dispose surfactantSignal

// [terminal -- no further instructions; exit node for CFG]

module dropletGenerationDetection
module dropletReaderDetection

manifest AAV_Sample
manifest ddPCR_Supermix
manifest PrimerY87
manifest PrimerY88
manifest Probe_FAM
manifest NucleaseFreeH2O
manifest PositiveControl_DNA
manifest DropletGenerationOil
manifest DropletReaderOil

// ============================================================
// Viral Titer Quantification by Droplet Digital PCR
// Protocol VC0005 - Quantification of rAAV Viral Vectors
//
// Assay: TaqMan ddPCR targeting AAV ITR region.
//   Forward primer Y87: GGAACCCCTAGTGATGGAGTT (100 uM, IDT)
//   Reverse primer Y88: CGGCCTCAGTGAGCGA (100 uM, IDT)
//   Probe: /56FAM/CGCGCAGAG/ZEN/AGGGAGTGG/3IABkFQ/ (100 uM, IDT)
//
// Master Mix composition (per full plate prep):
//   2112 uL 2x ddPCR Supermix (Bio-Rad 1863025)
//   1833.4 uL Nuclease-Free H2O
//   38 uL Y87 primer
//   38 uL Y88 primer
//   10.6 uL FAM probe
//
// Each PCR reaction: 31.5 uL master mix + 1.5 uL diluted sample.
//   Total reaction volume loaded to cartridge: 22.2 uL.
//   Droplet generation oil volume per well: 70 uL.
//   Droplets transferred to ddPCR plate: 40 uL.
//
// Serial dilution scheme (7 steps, 96-well non-skirted PCR plate):
//   Dilution 1: 1 uL virus + 39 uL H2O  -> factor 1:40  (2.5e-2)
//   Dilution 2: 10 uL D1 + 90 uL H2O   -> factor 1:10  (2.5e-3)
//   Dilution 3: 10 uL D2 + 90 uL H2O   -> factor 1:10  (2.5e-4)
//   Dilution 4: 10 uL D3 + 90 uL H2O   -> factor 1:10  (2.5e-5)
//   Dilution 5: 10 uL D4 + 90 uL H2O   -> factor 1:10  (2.5e-6)
//   Dilution 6: 10 uL D5 + 90 uL H2O   -> factor 1:10  (2.5e-7)
//   Dilution 7: 10 uL D6 + 90 uL H2O   -> factor 1:10  (2.5e-8)
//
// Dilutions 4-7 loaded into PCR reactions (linear detection range).
//
// PCR cycling conditions:
//   95 C  10 min        (enzyme activation)
//   94 C  30 s  \
//   60 C  60 s   > x40  (amplification)
//   98 C  10 min        (signal stabilisation)
//    4 C  hold
//
// Titer calculation:
//   Find dilutions in linear ddPCR range (100-10,000 copies/uL).
//   Average those concentrations and back-calculate viral genome
//   copies per mL accounting for dilution factors.
//   Positive control check: iDreV at 103 ng/uL should read
//   300-700 copies/uL in the 2.5e-6 dilution well.
//
// NOTE ON SSA AND SPLIT AVOIDANCE:
//   lilott8/BioScript enforces strict single-assignment: every
//   variable may be consumed (appear on the RHS of mix/detect/
//   heat/dispose/drain) exactly once. The split keyword
//   (syntax: result = split source into N) produces an N-element
//   array, but ALL N elements must be consumed or the compiler
//   flags stranded droplets (see moazami_world_to_chip_dmf.bs).
//   To avoid both SSA double-use and stranded-split errors, this
//   file uses independent dispense calls for every token that
//   must appear in more than one position. Each manifest
//   (ddPCR_Supermix, NucleaseFreeH2O, etc.) is a reservoir that
//   can be dispensed from multiple times; each dispense produces
//   a unique SSA token consumed exactly once downstream.
//
//   Serial dilution chain: purely linear (D1->D2->...->D7).
//   Each dilution variable is consumed only by the next dilution
//   step. PCR reactions receive independently dispensed aliquots
//   representing the corresponding concentration level.
//
// CFG STRUCTURE:
//   BB1  main               -- master mix prep; serial dilutions;
//                              droplet generation; PCR cycling;
//                              droplet reader run
//   BB2  readerPass         -- readerSignal > 0: valid droplet count
//                              and amplitude detected; dispose plate
//   BB3  readerFail         -- readerSignal <= 0: invalid read;
//                              drain and flag for repeat
//   BB4  readerJoin         -- join: positive control QC branch
//   BB5  controlPass        -- controlSignal > 0: iDreV in expected
//                              range (300-700 copies/uL); dispose
//   BB6  controlFail        -- controlSignal <= 0: out of range;
//                              drain; repeat assay
//   BB7  finalCleanup       -- terminal: dispose QC signal; end
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prepare 2x ddPCR master mix.
//   Combine Supermix, nuclease-free H2O, Y87 primer,
//   Y88 primer, and FAM probe in a 5 mL Eppendorf tube.
//   Vortex briefly; spin down before use.
//
//   Five independent master mix builds are performed -- one
//   per reaction (D4, D5, D6, D7, positive control) -- each
//   consuming its own unique dispense tokens. This avoids
//   split entirely while preserving SSA correctness.
//   Each mmX_* variable is consumed exactly once by its
//   corresponding reaction mix step below.
// ------------------------------------------------------------

// Master mix for reaction D4
mm4_supermix     = dispense 1 units of ddPCR_Supermix
mm4_h2o          = dispense 1 units of NucleaseFreeH2O
mm4_y87          = dispense 1 units of PrimerY87
mm4_y88          = dispense 1 units of PrimerY88
mm4_probe        = dispense 1 units of Probe_FAM
mm4_s1           = mix mm4_supermix with mm4_h2o for 5s
mm4_s2           = mix mm4_s1 with mm4_y87 for 5s
mm4_s3           = mix mm4_s2 with mm4_y88 for 5s
masterMix4       = mix mm4_s3 with mm4_probe for 5s

// Master mix for reaction D5
mm5_supermix     = dispense 1 units of ddPCR_Supermix
mm5_h2o          = dispense 1 units of NucleaseFreeH2O
mm5_y87          = dispense 1 units of PrimerY87
mm5_y88          = dispense 1 units of PrimerY88
mm5_probe        = dispense 1 units of Probe_FAM
mm5_s1           = mix mm5_supermix with mm5_h2o for 5s
mm5_s2           = mix mm5_s1 with mm5_y87 for 5s
mm5_s3           = mix mm5_s2 with mm5_y88 for 5s
masterMix5       = mix mm5_s3 with mm5_probe for 5s

// Master mix for reaction D6
mm6_supermix     = dispense 1 units of ddPCR_Supermix
mm6_h2o          = dispense 1 units of NucleaseFreeH2O
mm6_y87          = dispense 1 units of PrimerY87
mm6_y88          = dispense 1 units of PrimerY88
mm6_probe        = dispense 1 units of Probe_FAM
mm6_s1           = mix mm6_supermix with mm6_h2o for 5s
mm6_s2           = mix mm6_s1 with mm6_y87 for 5s
mm6_s3           = mix mm6_s2 with mm6_y88 for 5s
masterMix6       = mix mm6_s3 with mm6_probe for 5s

// Master mix for reaction D7
mm7_supermix     = dispense 1 units of ddPCR_Supermix
mm7_h2o          = dispense 1 units of NucleaseFreeH2O
mm7_y87          = dispense 1 units of PrimerY87
mm7_y88          = dispense 1 units of PrimerY88
mm7_probe        = dispense 1 units of Probe_FAM
mm7_s1           = mix mm7_supermix with mm7_h2o for 5s
mm7_s2           = mix mm7_s1 with mm7_y87 for 5s
mm7_s3           = mix mm7_s2 with mm7_y88 for 5s
masterMix7       = mix mm7_s3 with mm7_probe for 5s

// Master mix for positive control reaction
mmC_supermix     = dispense 1 units of ddPCR_Supermix
mmC_h2o          = dispense 1 units of NucleaseFreeH2O
mmC_y87          = dispense 1 units of PrimerY87
mmC_y88          = dispense 1 units of PrimerY88
mmC_probe        = dispense 1 units of Probe_FAM
mmC_s1           = mix mmC_supermix with mmC_h2o for 5s
mmC_s2           = mix mmC_s1 with mmC_y87 for 5s
mmC_s3           = mix mmC_s2 with mmC_y88 for 5s
masterMixCtrl    = mix mmC_s3 with mmC_probe for 5s

// ------------------------------------------------------------
// STEP 2: Serial dilution chain (purely linear, D1 to D7).
//   Each variable is consumed exactly once by the next step.
//   No variable appears on more than one RHS (SSA satisfied).
//   Add 39 uL H2O to row 1, then 1 uL sample (1:40 = 2.5e-2).
//   Rows 2-7: 10 uL from previous row into 90 uL H2O (1:10 each).
//   Mix by pipetting up and down 10-20 times per row.
// ------------------------------------------------------------

h2o_d1           = dispense 1 units of NucleaseFreeH2O
sampleRaw        = dispense 1 units of AAV_Sample
dilution1        = mix sampleRaw with h2o_d1 for 10s

h2o_d2           = dispense 1 units of NucleaseFreeH2O
dilution2        = mix dilution1 with h2o_d2 for 10s

h2o_d3           = dispense 1 units of NucleaseFreeH2O
dilution3        = mix dilution2 with h2o_d3 for 10s

h2o_d4           = dispense 1 units of NucleaseFreeH2O
dilution4        = mix dilution3 with h2o_d4 for 10s

h2o_d5           = dispense 1 units of NucleaseFreeH2O
dilution5        = mix dilution4 with h2o_d5 for 10s

h2o_d6           = dispense 1 units of NucleaseFreeH2O
dilution6        = mix dilution5 with h2o_d6 for 10s

h2o_d7           = dispense 1 units of NucleaseFreeH2O
dilution7        = mix dilution6 with h2o_d7 for 10s

// Store dilution plate at 4 C after sealing with Microseal B.
heat dilution7 at 4c for 60s

// ------------------------------------------------------------
// STEP 3: Assemble PCR reactions.
//   Add 31.5 uL master mix + 1.5 uL dilution to each tube.
//   Reactions use D4-D7 (2.5e-5 through 2.5e-8).
//   Each dilutionX_rxn is a fresh independent dispense from
//   the AAV_Sample manifest representing that concentration
//   level (abstraction for aliquoting from the dilution plate).
//   Vortex and spin down twice before droplet generation.
// ------------------------------------------------------------

d4_rxn           = dispense 1 units of AAV_Sample
d5_rxn           = dispense 1 units of AAV_Sample
d6_rxn           = dispense 1 units of AAV_Sample
d7_rxn           = dispense 1 units of AAV_Sample

reaction4        = mix masterMix4 with d4_rxn for 5s
reaction5        = mix masterMix5 with d5_rxn for 5s
reaction6        = mix masterMix6 with d6_rxn for 5s
reaction7        = mix masterMix7 with d7_rxn for 5s

heat reaction4 at 20c for 10s
heat reaction5 at 20c for 10s
heat reaction6 at 20c for 10s
heat reaction7 at 20c for 10s

// ------------------------------------------------------------
// STEP 4: Prepare positive control reaction.
//   iDreV positive control DNA (103 ng/uL, 7453 bp).
//   Expected: 300-700 copies/uL at 2.5e-6 dilution.
// ------------------------------------------------------------

posCtrlDNA       = dispense 1 units of PositiveControl_DNA
h2o_ctrl         = dispense 1 units of NucleaseFreeH2O
ctrlDiluted      = mix posCtrlDNA with h2o_ctrl for 5s
controlReaction  = mix masterMixCtrl with ctrlDiluted for 5s

heat controlReaction at 20c for 10s

// ------------------------------------------------------------
// STEP 5: Droplet generation.
//   Pour Droplet Generation Oil (Bio-Rad 1863005) into reservoir.
//   Load 22.2 uL of each sample reaction into middle row of
//   DG8 cartridge (Bio-Rad 1864007).
//   Load 70 uL Droplet Generation Oil slowly into bottom row.
//   Cover with gasket; generate droplets on QX200 generator.
//   Target: ~20,000 droplets per well (~0.85 nL each).
//   Transfer 40 uL of droplets to ddPCR 96-Well Plate.
//   Seal with pierceable foil heat seal (Bio-Rad 1814040).
//
//   Each reaction receives its own unique oil dispense token.
// ------------------------------------------------------------

dgOil_4          = dispense 1 units of DropletGenerationOil
dgOil_5          = dispense 1 units of DropletGenerationOil
dgOil_6          = dispense 1 units of DropletGenerationOil
dgOil_7          = dispense 1 units of DropletGenerationOil
dgOil_ctrl       = dispense 1 units of DropletGenerationOil

droplets4        = mix reaction4 with dgOil_4 for 30s
droplets5        = mix reaction5 with dgOil_5 for 30s
droplets6        = mix reaction6 with dgOil_6 for 30s
droplets7        = mix reaction7 with dgOil_7 for 30s
dropletsCtrl     = mix controlReaction with dgOil_ctrl for 30s

// ------------------------------------------------------------
// STEP 6: PCR cycling.
//   95 C  10 min   (hot-start polymerase activation; 600 s)
//   94 C  30 s  \
//   60 C  60 s   > x40 cycles
//   98 C  10 min   (final signal stabilisation; 600 s)
//    4 C  hold     (until droplet reader transfer)
//
//   Multi-cycle programme unrolled as accumulated heat steps
//   (BioScript has no loop construct):
//     40 x 30 s = 1200 s at 94 C  (total denaturation time)
//     40 x 60 s = 2400 s at 60 C  (total annealing/extension)
// ------------------------------------------------------------

// Stage 1: Initial denaturation (95 C, 600 s).
heat droplets4 at 95c for 600s
heat droplets5 at 95c for 600s
heat droplets6 at 95c for 600s
heat droplets7 at 95c for 600s
heat dropletsCtrl at 95c for 600s

// Stage 2: 40-cycle denaturation (94 C, 1200 s total).
heat droplets4 at 94c for 1200s
heat droplets5 at 94c for 1200s
heat droplets6 at 94c for 1200s
heat droplets7 at 94c for 1200s
heat dropletsCtrl at 94c for 1200s

// Stage 3: 40-cycle annealing/extension (60 C, 2400 s total).
heat droplets4 at 60c for 2400s
heat droplets5 at 60c for 2400s
heat droplets6 at 60c for 2400s
heat droplets7 at 60c for 2400s
heat dropletsCtrl at 60c for 2400s

// Stage 4: Signal stabilisation (98 C, 600 s).
heat droplets4 at 98c for 600s
heat droplets5 at 98c for 600s
heat droplets6 at 98c for 600s
heat droplets7 at 98c for 600s
heat dropletsCtrl at 98c for 600s

// Stage 5: Hold at 4 C until droplet reader transfer (60 s).
heat droplets4 at 4c for 60s
heat droplets5 at 4c for 60s
heat droplets6 at 4c for 60s
heat droplets7 at 4c for 60s
heat dropletsCtrl at 4c for 60s

// ------------------------------------------------------------
// STEP 7: Droplet reader setup and run.
//   Open QuantaSoft software; load template ITR-Shenqin-24.
//   Template settings per well:
//     Sample name | ABS | ddPCR mMix no dUTP | FAM | Ch1 Unknown
//   Place ddPCR plate in reader; orient with black clasps down.
//   Prime using QuantaSoft prime button.
//   Load Droplet Reader Oil (Bio-Rad 1863004) before priming.
//   Run experiment: FAM/VIC mode, reading by row.
//   Amplitude threshold: set to 1000 in QuantaSoft software.
//
//   Each plateWell requires its own unique reader oil token.
// ------------------------------------------------------------

readerOil_4      = dispense 1 units of DropletReaderOil
readerOil_5      = dispense 1 units of DropletReaderOil
readerOil_6      = dispense 1 units of DropletReaderOil
readerOil_7      = dispense 1 units of DropletReaderOil
readerOil_ctrl   = dispense 1 units of DropletReaderOil

plateWell4       = mix droplets4 with readerOil_4 for 5s
plateWell5       = mix droplets5 with readerOil_5 for 5s
plateWell6       = mix droplets6 with readerOil_6 for 5s
plateWell7       = mix droplets7 with readerOil_7 for 5s
plateWellCtrl    = mix dropletsCtrl with readerOil_ctrl for 5s

// dropletReaderDetection abstracts QuantaSoft readout.
// Returns positive signal if valid droplet count (>10,000/well)
// and clear FAM+/FAM- population separation are detected.
readerSignal4    = detect dropletReaderDetection on plateWell4 for 60s
readerSignal5    = detect dropletReaderDetection on plateWell5 for 60s
readerSignal6    = detect dropletReaderDetection on plateWell6 for 60s
readerSignal7    = detect dropletReaderDetection on plateWell7 for 60s

// ============================================================
// BB2 / BB3: Droplet reader QC gate (keyed on D4; highest signal).
// Pass (BB2): readerSignal4 > 0 -> valid read; dispose wells.
// Fail (BB3): readerSignal4 <= 0 -> bad read; drain all wells.
// Both branches converge at BB4 (readerJoin).
// ============================================================

if (readerSignal4 > 0) {
    dispose plateWell4
    dispose plateWell5
    dispose plateWell6
    dispose plateWell7
} else {
    drain plateWell4
    drain plateWell5
    drain plateWell6
    drain plateWell7
}

// ============================================================
// BB4: readerJoin
// Dispose reader QC signals for D4-D7. Proceed to positive
// control QC branch (BB5/BB6).
// ============================================================

dispose readerSignal4
dispose readerSignal5
dispose readerSignal6
dispose readerSignal7

// ------------------------------------------------------------
// STEP 8: Positive control QC.
//   dropletReaderDetection applied to control well.
//   Expected: iDreV reads 300-700 copies/uL at 2.5e-6 dilution.
//   If in range: proceed to titer calculation and reporting.
//   Titer calculation (off-chip in QuantaSoft):
//     Find linear range (100-10,000 copies/uL) across D4-D7;
//     average concentrations; back-calculate genome copies/mL
//     accounting for dilution factor and 1.5 uL input volume.
// ------------------------------------------------------------

controlSignal    = detect dropletReaderDetection on plateWellCtrl for 60s

// ============================================================
// BB5 / BB6: Positive control QC gate.
// Pass (BB5): controlSignal > 0 -> iDreV in expected range;
//             dispose control well; report titer.
// Fail (BB6): controlSignal <= 0 -> out of range;
//             drain; investigate master mix and cycling.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (controlSignal > 0) {
    dispose plateWellCtrl
} else {
    drain plateWellCtrl
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose positive control QC signal. Experiment ends.
// Clean hood and bench with 70% ethanol.
// Dispose biohazard waste per institutional guidelines.
// ============================================================

dispose controlSignal

// [terminal -- no further instructions; exit node for CFG]
